INSERT INTO review_deck_versions (deck_id, version, content_hash, source_hashes, imported_at) VALUES ($t$0-fullstack-mastery/0-module-1$t$, '231d8cc57', $t$a23777fc32d3d302e48920cd6882db9f5c87bfa747ba82922096ece02a0abc7c$t$, $j${"cards/0-card/en.md":"70d920dcb8d939949ded6e2d6af4a4e26fc200a545f3ae67ecac3809569cb6ce","cards/0-card/vi.md":"e1a6140279efe537e0b87d8408792002d7e66d3eb208d66c0542905b7ad2c2c6","cards/1-card/en.md":"5ffde4b0314bf0fa65b047d51728c6565e83287484f2fedd612f2e0175982b3c","cards/1-card/vi.md":"05a407d360c866d789607bf52a0945225e78a286313dafbe29b5a2d1621c54d5","cards/10-card/en.md":"efd0252ae82924d62ff1f7d6035c55e473a9ee6ed906f0ac4288ea9e9c19309b","cards/10-card/vi.md":"e9b175cc7d9cc7d1cf717556fdaae84023798c0b071b0aec651068884a058239","cards/11-card/en.md":"b3315e060cd5c9a0003c047b09fbda6543c6f62b767b8094312be40edcf68342","cards/11-card/vi.md":"54edb3f6ced826d44a9510901002b9ea49e52104fbc08433a480f9720c2c5d51","cards/12-card/en.md":"97db2edfee3a162ad369a9e26d1f08259f319b714d557fceabc2f711adda5cc6","cards/12-card/vi.md":"967c00a4df183ae3b0b7e3e3cc1ddca1cd8407939d9291d5384d5c777a043ce7","cards/13-card/en.md":"dc776c2c258f7d84bc33f9143f2114b65947d9516759fc68035e37ac8ba55671","cards/13-card/vi.md":"d703b65d52f7ffc52ac1891a014688d7b6865e3fab8ac4b31943fb544dbcc2dc","cards/14-card/en.md":"afcccf20c62174458adc488d4960caeea5f8d48b79886f52510e21fb9e573f89","cards/14-card/vi.md":"902de627001eec3113c044ed6ce845b1d89879af007e4e790f8ece2b868cc2c3","cards/15-card/en.md":"d21ea2749ea7a611ccc1d6f699a820fcb07e4a64e7b1b1953fd541e0141a9672","cards/15-card/vi.md":"55625596817863d640df3d72be30f5889e7e78e73d2bf3241c91efa7a3834b85","cards/16-card/en.md":"ffc88815a17cc2310879c271021b630cd9afa18515211a7b6c021055021e3be7","cards/16-card/vi.md":"84f4b567a3fdd3bba4dbbe1bd57603a8b4749098727c8890575cbd010dfa3b79","cards/17-card/en.md":"f16d5d2ab13650352b179aabc9fdd5507e10ecc00d6d6325fee32e809e6d9a44","cards/17-card/vi.md":"4559d7b9cb9eaa00f1b48fbb2a5164916500e94aa2466a4baed503315e8a4