INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/0-module-1/0$t$, '231d8cc57', $t$0-fullstack-mastery/0-module-1$t$, 0, false, $t$junior$t$, NULL, $j${"vi":{"question":"Bạn cần một service phụ thuộc vào service khác. Vì sao nên giao việc tạo dependency đó cho một container thay vì tự tay tạo nó ở bất kỳ đâu bạn cần?","tags":["Dependency Injection","Architecture"]},"en":{"question":"You need one service to depend on another. Why hand that dependency's creation over to a container instead of just constructing it yourself wherever you need it?","tags":["Dependency Injection","Architecture"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nTự tay tạo khiến bạn gắn cứng vào một implementation cụ thể, mỗi lần tạo lại sinh ra một bản riêng (mất chia sẻ), và khoá test của bạn vào đúng object thật đó. Giao việc tạo cho một {{c1::container::factory function,service locator}} đem lại khả năng test (thay bằng mock), loose coupling (đổi implementation mà không đụng consumer), và quản lý lifecycle tập trung.\n\n:::muted\nCơ chế\n:::\nMột component khai báo nó cần gì qua tham số constructor; container đọc các khai báo đó, dựng dependency graph theo đúng thứ tự, tạo mỗi instance đúng một lần, rồi inject vào. Bạn không bao giờ tự khởi tạo dependency — bạn chỉ khai báo ý định.\n\n:::muted\nBẫy thường gặp\n:::\nMột dependency tự tay tạo bên trong 1 class khiến class đó không thể unit-test được nếu không dựng luôn cái thật. Và nếu hai chỗ khác nhau đều tự tạo \"cùng\" một dependency, bạn âm thầm mất hẳn cam kết chia sẻ một instance duy nhất.\n\n:::muted\nĐào sâu tiếp\n:::\nnếu cùng một service bị tạo nhầm ở hai chỗ khác nhau, bug quan sát được là gì với một thứ vốn phải giữ state dùng chung?","clozes":[{"n":1,"term":"container","distractors":["factory function","service locator"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nConstructing it yourself hard-wires you to one concrete implementation, spins up a private copy every time you do it (no sharing), and locks your tests to the real object. Handing creation to a {{c1::container::factory function,service locator}} buys testability (swap in a mock), loose coupling (swap implementations without touching consumers), and centralized lifecycle management.\n\n:::muted\nHow it works\n:::\nA component declares what it needs via its constructor's parameters; the container reads those, builds the dependency graph in the right order, creates each instance once, and injects it. You never instantiate a dependency yourself — you only declare intent.\n\n:::muted\nCommon pitfall\n:::\nA hand-built dependency inside a class makes that class impossible to unit-test without spinning up the real thing. And if two different places each construct the \"same\" dependency themselves, you silently lose the one-shared-instance guarantee entirely.\n\n:::muted\nGo deeper\n:::\nif the same service gets constructed in two different places by mistake, what observable bug does that cause for something that's supposed to hold shared state?","clozes":[{"n":1,"term":"container","distractors":["factory function","service locator"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/0-module-1/1$t$, '231d8cc57', $t$0-fullstack-mastery/0-module-1$t$, 1, false, $t$middle$t$, $t$go$t$, $j${"vi":{"question":"Một ngôn ngữ như Go không có sẵn dependency-injection container — bạn không được auto-wiring miễn phí. Vậy làm sao vẫn đảm bảo \"một instance dùng chung ở mọi nơi\", và bạn đánh đổi gì khi không có framework làm việc đó?","tags":["Dependency Injection","Architecture"]},"en":{"question":"A language like Go has no built-in dependency-injection container — you don't get automatic wiring for free. How do you still guarantee \"one shared instance used everywhere\", and what do you trade for not having a framework do it?","tags":["Dependency Injection","Architecture"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nKhông có container, việc wiring diễn ra thủ công tại {{c1::composition root::dependency graph,constructor function}} (thường là hàm main): bạn tạo mỗi dependency đúng một lần rồi truyền cùng một pointer vào mọi constructor function cần nó. Bạn đánh đổi quản lý lifecycle tự động lấy một dependency graph tường minh, thấy được toàn bộ.\n\n:::muted\nCơ chế\n:::\nKhông có bước runtime nào đọc kiểu tham số constructor — bạn tự viết code wiring, đúng một lần, ngay ở entry point. Mọi constructor function phía sau chỉ nhận dependency đã dựng sẵn như một argument bình thường.\n\n:::muted\nTrade-off\n:::\nLợi: toàn bộ graph nằm gọn trong một file, không gì bị suy luận ngầm lúc runtime, dễ suy luận ở quy mô nhỏ-vừa. Hại: bạn tự chịu trách nhiệm kỷ luật lifecycle và chia sẻ — không gì ngăn bạn vô tình tạo cùng một service hai lần ở hai chỗ khác nhau.\n\n:::muted\nBẫy thường gặp\n:::\nGọi constructor function ở nhiều hơn một chỗ \"cho chắc\" và bạn âm thầm có hai instance độc lập — state của cái này không bao giờ tới được cái kia. Quy ước ngăn điều này: chỉ tạo đúng một lần, duy nhất tại composition root.\n\n:::muted\nĐào sâu tiếp\n:::\nkhi app của bạn có hơn 30 service wiring tay tại composition root, file đó bắt đầu trông như thế nào, và khi nào nỗi đau đó thật sự đáng để chuyển sang dùng container?","clozes":[{"n":1,"term":"composition root","distractors":["dependency graph","constructor function"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nWithout a container, wiring happens manually at the {{c1::composition root::dependency graph,constructor function}} (typically the main function): you create each dependency exactly once and pass the same pointer into every constructor function that needs it. You trade automatic lifecycle management for an explicit, fully visible dependency graph.\n\n:::muted\nHow it works\n:::\nThere is no runtime step reading constructor types — you write the wiring code yourself, once, at the entry point. Every downstream constructor function just receives the already-built dependency as a plain argument.\n\n:::muted\nTrade-off\n:::\nThe upside: the whole graph is visible in one file, nothing is inferred at runtime, easier to reason about at small-to-medium scale. The downside: you own lifecycle and sharing discipline yourself — nothing stops you from accidentally constructing the same service twice in two different places.\n\n:::muted\nCommon pitfall\n:::\nCall the constructor function in more than one place \"just to be safe\" and you silently get two independent instances — any state one of them holds never reaches the other. The convention that prevents this: construct exactly once, only at the composition root.\n\n:::muted\nGo deeper\n:::\nonce your app has 30+ services wired by hand at the composition root, what does that file start to look like, and when is that pain actually worth reaching for a container?","clozes":[{"n":1,"term":"composition root","distractors":["dependency graph","constructor function"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/0-module-1/2$t$, '231d8cc57', $t$0-fullstack-mastery/0-module-1$t$, 2, false, $t$junior$t$, NULL, $j${"vi":{"question":"Handler của bạn nhận một request. Vì sao input validation nên xảy ra trước khi request chạm tới business logic, thay vì bên trong chính service?","tags":["Request Pipeline","Validation"]},"en":{"question":"Your handler receives a request. Why should input validation happen before the request ever reaches your business logic, rather than inside the service itself?","tags":["Request Pipeline","Validation"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nChặn input xấu ngay tại {{c1::boundary::handler,database layer}} nghĩa là business logic chỉ bao giờ thấy dữ liệu sạch, và mọi lần từ chối trả về cùng một hình dạng nhất quán mà không tốn tài nguyên cho việc chắc chắn sẽ thất bại. Validate bên trong service vừa quá trễ vừa bị lặp lại ở mọi nơi gọi tới.\n\n:::muted\nCơ chế\n:::\nMột tầng validation riêng chạy trước handler; request fail validation bị cắt ngang ngay lập tức, nên cùng một check không bao giờ phải viết lại hai lần ở các call site khác nhau cho cùng một dạng input.\n\n:::muted\nBẫy thường gặp\n:::\nChuyển check vào service và giờ bạn phải giữ nó ở đó CỘNG THÊM ở mọi chỗ khác gọi tới service đó — quên cập nhật một chỗ, nó âm thầm tin tưởng input chưa validate trở lại.\n\n:::muted\nĐào sâu tiếp\n:::\ntầng validation của bạn chỉ bọc request HTTP — điều gì xảy ra với cam kết đó khi cùng service giờ được gọi bởi một message queue hay một sự kiện WebSocket thay vì HTTP?","clozes":[{"n":1,"term":"boundary","distractors":["handler","database layer"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nBlocking bad input at the {{c1::boundary::handler,database layer}} means the business logic only ever sees clean data, and every rejection returns a consistent shape without spending any resources on work that was certain to fail anyway. Validating inside the service is both too late and gets duplicated across every caller.\n\n:::muted\nHow it works\n:::\nA dedicated validation layer runs before the handler; a request that fails validation gets short-circuited immediately, so the same check never needs to be written twice across different call sites for the same input shape.\n\n:::muted\nCommon pitfall\n:::\nMove the check into the service and you now own it there PLUS at every other place that same service gets called from — miss updating one, and it silently trusts unvalidated input again.\n\n:::muted\nGo deeper\n:::\nyour validation layer only wraps HTTP requests — what happens to that guarantee for the same service now triggered by a queue message or a WebSocket event instead?","clozes":[{"n":1,"term":"boundary","distractors":["handler","database layer"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/0-module-1/3$t$, '231d8cc57', $t$0-fullstack-mastery/0-module-1$t$, 3, true, $t$middle$t$, NULL, $j${"vi":{"question":"Framework của bạn cho phép chạy check \"caller này có được phép không\" và check \"dữ liệu này có đúng hình dạng không\" như hai tầng pipeline riêng biệt, theo thứ tự cố định. Vì sao giữ chúng thành hai tầng khác nhau thay vì gộp một check duy nhất, và tầng nào phải chạy trước?","tags":["Request Pipeline","Authorization"]},"en":{"question":"Your framework lets you run an \"is this caller allowed?\" check and an \"is this data shaped right?\" check as two separate pipeline stages, in a fixed order. Why keep them as two different layers instead of one combined check, and which one has to run first?","tags":["Request Pipeline","Authorization"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nMột {{c1::gate layer::validation layer,business logic layer}} trả lời \"request này có được phép tiếp tục không\" (authentication/authorization) và phải chạy trước; một {{c2::validation layer::gate layer,business logic layer}} trả lời \"dữ liệu có đúng hình dạng không\" và chỉ quan trọng khi đã biết caller được phép có mặt ở đó. Gộp cả hai vào một check khiến logic đó không thể tái sử dụng hay test riêng lẻ.\n\n:::muted\nCơ chế\n:::\nVì gate chạy trước, một caller không được phép còn chưa kịp chạm tới chi phí validate hay transform payload — bạn từ chối theo cách rẻ trước khi tốn công cho check đắt hơn.\n\n:::muted\nBẫy thường gặp\n:::\nNhồi một role check vào tầng validation và nó âm thầm mất đi metadata kiểu tham số mà validator vốn có, nên authorization giờ phải tự parse raw body — và đó là thứ đầu tiên bị bỏ sót mỗi khi hình dạng route thay đổi.\n\n:::muted\nĐào sâu tiếp\n:::\nnếu authorization thật ra cần một field chỉ tồn tại SAU KHI validation transform raw body — bạn đặt check đó ở đâu thay vào đó?","clozes":[{"n":1,"term":"gate layer","distractors":["validation layer","business logic layer"]},{"n":2,"term":"validation layer","distractors":["gate layer","business logic layer"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nA {{c1::gate layer::validation layer,business logic layer}} answers \"may this request proceed at all\" (authentication/authorization) and must run first; a {{c2::validation layer::gate layer,business logic layer}} answers \"is the data well-formed\" and only matters once you already know the caller is allowed to be there. Mixing the two into one check makes that logic impossible to reuse or test in isolation.\n\n:::muted\nHow it works\n:::\nBecause the gate runs first, an unauthorized caller never even reaches the cost of validating or transforming their payload — you reject the cheap way before spending effort on the more expensive check.\n\n:::muted\nCommon pitfall\n:::\nCram a role check into your validation layer and it silently loses the parameter-type metadata your validator normally has, so authorization now has to hand-parse the raw body — and it's the first thing skipped whenever the route shape changes.\n\n:::muted\nGo deeper\n:::\nwhat if authorization actually needs a field that only exists after validation transforms the raw body — where do you put that check instead?","clozes":[{"n":1,"term":"gate layer","distractors":["validation layer","business logic layer"]},{"n":2,"term":"validation layer","distractors":["gate layer","business logic layer"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/0-module-1/4$t$, '231d8cc57', $t$0-fullstack-mastery/0-module-1$t$, 4, true, $t$junior$t$, NULL, $j${"vi":{"question":"Vì sao phải mất công tách mọi giá trị phụ thuộc môi trường ra thành config, thay vì chỉ rải các check \"nếu môi trường là production\" khắp nơi trong code cần đến?","tags":["Configuration","Architecture"]},"en":{"question":"Why go to the trouble of pulling every environment-dependent value out into config, instead of just scattering \"if environment is production\" checks through the code where they're needed?","tags":["Configuration","Architecture"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nTách config cho phép đúng một bản build chạy ở mọi môi trường — chỉ giá trị thay đổi, code không bao giờ đổi. Các điều kiện môi trường rải rác khắp nơi biến mỗi chỗ đó thành nơi một sai sót (hay một {{c1::secret::hostname,log level}} bị lộ) có thể ẩn náu, và không chỗ nào dễ test riêng lẻ.\n\n:::muted\nCơ chế\n:::\nConfig được gom vào một nguồn có kiểu duy nhất lúc boot; phần còn lại của codebase đọc qua nguồn đó thay vì bao giờ chạm trực tiếp vào biến môi trường thô.\n\n:::muted\nBẫy thường gặp\n:::\nNgay khi bạn cho phép đọc biến môi trường thô từ nhiều hơn một chỗ, bạn đã mất nguồn sự thật duy nhất — không gì ngăn một check thứ hai, hơi khác, trôi dạt khỏi cái đầu tiên.\n\n:::muted\nĐào sâu tiếp\n:::\nfile config của bạn thiếu một biến mà code phụ thuộc vào — app nên boot với giá trị undefined rồi fail sau, hay từ chối boot luôn? Vì sao?","clozes":[{"n":1,"term":"secret","distractors":["hostname","log level"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nSeparating config lets the exact same build run in every environment — only the values change, never the code. Env conditionals scattered everywhere turn every one of those spots into a place a mistake (or a leaked {{c1::secret::hostname,log level}}) can hide, and none of them are easy to test in isolation.\n\n:::muted\nHow it works\n:::\nConfig is gathered into one typed source at boot; the rest of the codebase reads through that source instead of ever touching the raw environment directly.\n\n:::muted\nCommon pitfall\n:::\nThe moment you allow reading the raw environment from more than one place, you've lost your single source of truth — nothing stops a second, slightly different check from drifting away from the first.\n\n:::muted\nGo deeper\n:::\nyour config file is missing a variable your code depends on — should the app boot with it undefined and fail later, or refuse to boot at all? Why?","clozes":[{"n":1,"term":"secret","distractors":["hostname","log level"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/0-module-1/5$t$, '231d8cc57', $t$0-fullstack-mastery/0-module-1$t$, 5, true, $t$middle$t$, NULL, $j${"vi":{"question":"Việc gõ kiểu cho config (schema cộng một typed accessor) thật sự đem lại gì hơn so với chỉ đọc biến môi trường thô trực tiếp ở bất kỳ đâu bạn cần?","tags":["Configuration","Validation"]},"en":{"question":"What does typing your configuration (a schema plus a typed accessor) actually buy you over just reading the raw environment variable directly wherever you need it?","tags":["Configuration","Validation"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nConfig có kiểu biến tên key gõ sai hay sai kiểu thành lỗi {{c1::compile-time::runtime,lint-time}} kèm autocomplete, thay vì một undefined âm thầm chỉ nổ tung lần đầu code path đó chạy ở production. Cái giá là phải khai báo hình dạng trước.\n\n:::muted\nCơ chế\n:::\nMột schema validate biến môi trường thô đúng một lần lúc boot; phần còn lại của app đọc qua một typed accessor, nên biến thiếu hoặc sai dạng fail ồn ào ngay lúc khởi động thay vì âm thầm ở request thật đầu tiên chạm tới nó.\n\n:::muted\nBẫy thường gặp\n:::\nBỏ qua validate schema và một biến bắt buộc bị thiếu không làm fail lúc boot — nó fail ở request thật đầu tiên cần tới nó, lúc 3 giờ sáng, với một stack trace chẳng liên quan rõ ràng gì tới config.\n\n:::muted\nĐào sâu tiếp\n:::\nhai nguồn config đều định nghĩa cùng một key — loader của bạn quyết định cái nào thắng thế nào, và vì sao mô hình precedence đó quan trọng khi debug một giá trị sai ở production?","clozes":[{"n":1,"term":"compile-time","distractors":["runtime","lint-time"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nTyped config turns a mistyped key name or a wrong type into a {{c1::compile-time::runtime,lint-time}} error with autocomplete, instead of a silent undefined that only blows up the first time that code path runs in production. The cost is declaring the shape up front.\n\n:::muted\nHow it works\n:::\nA schema validates the raw environment once at boot; the rest of the app reads through a typed accessor, so a missing or malformed variable fails loudly at startup instead of quietly at the first request that happens to touch it.\n\n:::muted\nCommon pitfall\n:::\nSkip schema validation and a missing required variable doesn't fail the boot — it fails the first real request that needs it, at 3am, with a stack trace that has nothing obviously to do with config.\n\n:::muted\nGo deeper\n:::\ntwo config sources both define the same key — how does your loader decide which one wins, and why does that precedence model matter for debugging a wrong value in production?","clozes":[{"n":1,"term":"compile-time","distractors":["runtime","lint-time"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/0-module-1/6$t$, '231d8cc57', $t$0-fullstack-mastery/0-module-1$t$, 6, true, $t$junior$t$, NULL, $j${"vi":{"question":"Log của team bạn hiện chỉ là chuỗi in ra màn hình. Vì sao cách đó hết hiệu quả khi chạy production ở quy mô thật?","tags":["Logging","Observability"]},"en":{"question":"Your team's logs are just printed strings today. Why does that stop working once you're running in production at any real scale?","tags":["Logging","Observability"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nMột log {{c1::structured::colorized,verbose}} là một record với field thật (level, context, request id...) mà log aggregator có thể index, filter, và cảnh báo; một chuỗi in tự do không thể tách thành field và không mở rộng nổi quá vài dòng bạn thật sự đọc bằng mắt.\n\n:::muted\nCơ chế\n:::\nMỗi lời gọi log phát ra một object hay record, không phải một câu văn — aggregator nạp trực tiếp các field thay vì phải parse ý nghĩa ngược lại từ văn xuôi.\n\n:::muted\nTrade-off\n:::\nJSON có cấu trúc khó đọc bằng mắt hơn trên máy dev — hầu hết setup giải quyết bằng một bản render \"pretty\" riêng chỉ cho output local/console, vẫn giữ nguyên record có cấu trúc bên dưới.\n\n:::muted\nĐào sâu tiếp\n:::\nvì sao bạn lại cố tình chạy hai bản render log khác nhau — một view console có màu và một file JSON thuần — từ cùng một log event, thay vì chọn một định dạng duy nhất?","clozes":[{"n":1,"term":"structured","distractors":["colorized","verbose"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nA {{c1::structured::colorized,verbose}} log is a record with real fields (level, context, request id...) that a log aggregator can index, filter, and alert on; a free-form printed string can't be split into fields and doesn't scale past a handful of lines you'd actually read by eye.\n\n:::muted\nHow it works\n:::\nEvery log call emits an object or record, not a sentence — the aggregator ingests the fields directly instead of trying to parse meaning back out of prose.\n\n:::muted\nTrade-off\n:::\nStructured JSON is harder to read by eye on a dev machine — most setups solve this with a separate \"pretty\" rendering just for local/console output, keeping the same underlying structured record.\n\n:::muted\nGo deeper\n:::\nwhy would you deliberately run two different log renderings — a colored console view and a plain JSON file — off the exact same underlying log event, instead of picking one format?","clozes":[{"n":1,"term":"structured","distractors":["colorized","verbose"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/0-module-1/7$t$, '231d8cc57', $t$0-fullstack-mastery/0-module-1$t$, 7, true, $t$senior$t$, NULL, $j${"vi":{"question":"Framework của bạn tự phát ra log nội bộ riêng, và code ứng dụng của bạn log riêng bằng logger của chính nó. Vì sao phải mất công gộp cả hai vào một pipeline, và rủi ro nếu không làm vậy là gì?","tags":["Logging","Observability"]},"en":{"question":"Your framework emits its own internal logs, and your application code logs separately with its own logger. Why go to the trouble of merging both into one pipeline, and what's the risk if you don't?","tags":["Logging","Observability"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nHai logger song song nghĩa là hai định dạng và sink khác nhau cho thứ đáng lẽ phải là một câu chuyện liền mạch — tệ hơn, logger mặc định của framework thường vẫn chạy trừ khi bạn tắt nó tường minh, nên bạn âm thầm có log {{c1::trùng lặp::bị thiếu,sai thứ tự}} cho cùng một sự kiện. Một pipeline duy nhất cho mọi dòng log cùng hình dạng và cùng request id, từ lúc boot tới business logic.\n\n:::muted\nCơ chế\n:::\nBạn override logger mặc định/lúc bootstrap một cách tường minh để mọi log — dù nội bộ framework hay ứng dụng — đều chảy qua cùng một cấu hình transport và cùng một correlation id.\n\n:::muted\nBẫy thường gặp\n:::\nQuên tắt logger mặc định của framework trước khi gắn logger tuỳ chỉnh vào, và cả hai chạy song song — mọi sự kiện bị in hai lần, và một sink JSON kết thúc với các dòng trùng lặp phá hỏng bất kỳ thứ gì đếm hay dedupe dựa vào nó.\n\n:::muted\nĐào sâu tiếp\n:::\nsink file-transport của bạn chạm phải filesystem read-only và throw — điều đó nên làm crash cả app, hay logging nên xuống cấp một cách nhẹ nhàng? Vì sao?","clozes":[{"n":1,"term":"trùng lặp","distractors":["bị thiếu","sai thứ tự"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nTwo parallel loggers means two different formats and sinks for what should be one continuous story — and worse, the framework's own default logger usually still runs unless you explicitly disable it, so you silently get {{c1::duplicate::missing,out-of-order}} log lines for the same events. One pipeline gives every log line the same shape and the same request id, from boot to business logic.\n\n:::muted\nHow it works\n:::\nYou override the default/bootstrap logger explicitly so every log — framework-internal or application — funnels through the same transport configuration and the same correlation id.\n\n:::muted\nCommon pitfall\n:::\nForget to disable the framework's own default logger before wiring in your custom one, and both run side by side — every event gets printed twice, and a JSON sink ends up with duplicate lines that break anything counting or deduping on it.\n\n:::muted\nGo deeper\n:::\nyour file-transport sink hits a read-only filesystem and throws — should that crash the whole app, or should logging degrade gracefully? Why?","clozes":[{"n":1,"term":"duplicate","distractors":["missing","out-of-order"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/0-module-1/8$t$, '231d8cc57', $t$0-fullstack-mastery/0-module-1$t$, 8, true, $t$senior$t$, NULL, $j${"vi":{"question":"Bạn có một điểm xử lý lỗi toàn cục mà mọi exception chưa bắt đều chảy qua, nên mọi error response ra cùng một hình dạng. Điều gì xảy ra với cam kết đó ngay khi chính code xử lý lỗi lại throw?","tags":["Error Handling","Resilience"]},"en":{"question":"You have one global error-handling hook that every unhandled exception funnels through, so every error response comes out in the same shape. What happens to that guarantee the moment the error-handling code itself throws?","tags":["Error Handling","Resilience"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nBình thường điểm xử lý này bắt mọi exception và định hình nó thành một envelope nhất quán — bắt theo từng endpoint thay vào đó sẽ để mỗi route trôi dạt thành hình dạng lỗi riêng. Nhưng nếu logic của chính điểm xử lý này throw, không gì bắt được nó — framework rơi về handler mặc định thô, và bạn {{c1::để lộ::âm thầm bỏ,tự động retry}} một response hoàn toàn khác, không có hình dạng, đúng cho chính trường hợp bạn xây điểm xử lý để ngăn.\n\n:::muted\nCơ chế\n:::\nĐiểm xử lý nằm ở cuối cùng của pipeline và nhận đúng nghĩa mọi thứ chưa bắt — đó là điều làm cho một hợp đồng envelope duy nhất khả thi trên toàn hệ thống thay vì logic lặp lại theo từng controller mà cuối cùng ai đó sẽ quên.\n\n:::muted\nBẫy thường gặp\n:::\nGiữ thân của điểm xử lý này phòng thủ và tối giản — bọc bất cứ thứ gì có thể tự throw (dựng timestamp, đọc header) trong fallback riêng của nó, vì không có lưới an toàn nào bên dưới lưới an toàn của bạn.\n\n:::muted\nĐào sâu tiếp\n:::\nmột lỗi xảy ra giữa chừng, sau khi bạn đã bắt đầu ghi response body — bạn còn đổi được status code lúc đó không, và nên làm gì thay vào đó?","clozes":[{"n":1,"term":"để lộ","distractors":["âm thầm bỏ","tự động retry"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nNormally the hook catches every exception and shapes it into one consistent envelope — catching per-endpoint instead would let every route drift into its own error shape. But if the hook's own logic throws, nothing catches that — the framework falls back to its raw default handler, and you {{c1::leak::silently drop,automatically retry}} a completely different, unshaped response for exactly the case you built the hook to prevent.\n\n:::muted\nHow it works\n:::\nThe hook sits at the very end of the pipeline and receives literally everything unhandled — that's what makes one envelope contract possible system-wide instead of duplicated per-controller logic that someone eventually forgets.\n\n:::muted\nCommon pitfall\n:::\nKeep the hook's own body defensive and minimal — wrap anything that could itself throw (building a timestamp, reading a header) in its own fallback, because there is no safety net underneath your safety net.\n\n:::muted\nGo deeper\n:::\nan error happens mid-stream, after you've already started writing a response body — can you still change the status code at that point, and what should you do instead?","clozes":[{"n":1,"term":"leak","distractors":["silently drop","automatically retry"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/0-module-1/9$t$, '231d8cc57', $t$0-fullstack-mastery/0-module-1$t$, 9, true, $t$senior$t$, NULL, $j${"vi":{"question":"Message thật của một lỗi server không mong đợi thường chứa stack trace, một chuỗi SQL thô, hoặc chi tiết nội bộ. Vì sao bạn không bao giờ nên gửi nguyên văn message đó về client, dù nó có vẻ hữu ích để debug?","tags":["Error Handling","Security"]},"en":{"question":"An unexpected server error's real message often contains a stack trace, a raw SQL string, or an internal detail. Why should you never send that literal message back to the client, even though it might feel helpful for debugging?","tags":["Error Handling","Security"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nMessage thật của một lỗi không mong đợi để lộ cấu trúc nội bộ của bạn cho bất kỳ ai có thể kích hoạt nó, và dù sao cũng vô nghĩa với client — thay bằng một message {{c1::chung chung::rỗng,đã dịch}}, và chỉ giữ message thật trong log nội bộ nơi on-call thật sự dùng được nó để truy vết sự cố.\n\n:::muted\nCơ chế\n:::\nLỗi mong đợi (do lỗi client) nhận một message an toàn, có chủ đích, hướng tới client mà bạn viết ra cố ý; lỗi không mong đợi (do lỗi server) nhận một message chung chung đã che, còn chi tiết thật chỉ đi vào log — sự khác biệt là tiết lộ có chủ đích và tiết lộ ngoài ý muốn.\n\n:::muted\nBẫy thường gặp\n:::\nMột message validation do lỗi client có thể lộ tệ y hệt một lỗi không mong đợi — một message kiểu \"không tìm thấy user nào với đúng email này đã đăng ký\" vẫn tiết lộ email thật của một user hay tên cột nội bộ. Coi mọi message hướng tới client, kể cả cái có chủ đích, là dữ liệu công khai.\n\n:::muted\nĐào sâu tiếp\n:::\nenvelope lỗi hướng tới client của bạn mang một path và một timestamp nhưng không có chi tiết message — hai field đó cho phép support làm được gì mà một message chung chung mơ hồ một mình không làm được?","clozes":[{"n":1,"term":"chung chung","distractors":["rỗng","đã dịch"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nAn unexpected error's real message reveals your internal structure to anyone who can trigger it, and it's meaningless to the client anyway — swap it for a {{c1::generic::empty,translated}} message, and keep the real one only in your internal logs where on-call can actually use it to trace the incident.\n\n:::muted\nHow it works\n:::\nExpected (client-fault) errors get a deliberate, safe, client-facing message you wrote on purpose; unexpected (server-fault) errors get a masked generic message, with the real detail routed to logs only — the distinction is deliberate versus accidental disclosure.\n\n:::muted\nCommon pitfall\n:::\nA client-fault validation message can leak just as badly as an unexpected one — a message like \"no user found with that exact email already registered\" still discloses a real user's email or an internal column name. Treat every client-facing message, even a deliberate one, as public data.\n\n:::muted\nGo deeper\n:::\nyour client-facing error envelope carries a path and a timestamp but no message detail — what do those two fields let support actually do that a vague generic message alone can't?","clozes":[{"n":1,"term":"generic","distractors":["empty","translated"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/0-module-1/10$t$, '231d8cc57', $t$0-fullstack-mastery/0-module-1$t$, 10, true, $t$junior$t$, NULL, $j${"vi":{"question":"Bề mặt công khai của một module chỉ lộ ra đúng những gì được đánh dấu chia sẻ, và module khác chỉ chạm được vào qua đúng bề mặt đó. Vì sao làm ranh giới đó tường minh lại biến cả một lớp bug thành lỗi lúc khởi động thay vì lỗi lúc runtime?","tags":["Architecture","Module Boundaries"]},"en":{"question":"A module's public surface only exposes what's explicitly marked to be shared, and another module can only reach in through that surface. Why does making that boundary explicit turn a whole class of bugs into a startup-time failure instead of a runtime one?","tags":["Architecture","Module Boundaries"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nVì framework kiểm tra bề mặt {{c1::tường minh::ngầm định,tùy chọn}} đó ngay lúc boot — nếu một module với tới thứ module kia chưa bao giờ export ra, app từ chối khởi động thay vì trả về một null/undefined bí ẩn sâu trong một request handler về sau.\n\n:::muted\nCơ chế\n:::\nMỗi module khai báo nó tiêu thụ gì và lộ ra gì; việc wiring diễn ra đúng một lần, lúc khởi động, bằng cách duyệt qua đúng graph đã khai báo đó — nên một liên kết thiếu bị bắt trước khi bất kỳ request nào được phục vụ.\n\n:::muted\nTrade-off\n:::\nBạn trả giá cho sự an toàn này bằng thủ tục khai báo đầu vào — mọi dependency băng qua ranh giới đều phải khai báo, kể cả khi nó \"hiển nhiên\" nên chạy được luôn — không gì được chạm tới một cách ngầm định.\n\n:::muted\nBẫy thường gặp\n:::\nLộ ra mọi thứ theo mặc định để né thủ tục khai báo làm sụp đổ hoàn toàn ranh giới — một khi module nào cũng chạm được vào nội bộ module khác, danh sách export không còn nghĩa gì, và cái check fail-fast kia chẳng còn gì để kiểm.\n\n:::muted\nĐào sâu tiếp\n:::\nhai module cuối cùng đều cần export của nhau cùng lúc — hình dạng vòng tròn đó làm gì với graph khởi động, và cách sửa thật sự là gì?","clozes":[{"n":1,"term":"tường minh","distractors":["ngầm định","tùy chọn"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nBecause the framework checks the {{c1::explicit::implicit,optional}} surface at boot — if one module reaches for something the other never exposed, the app refuses to start instead of returning a mysterious null or undefined deep in a request handler later.\n\n:::muted\nHow it works\n:::\nEach module declares what it consumes and what it exposes; wiring happens once, at startup, by walking that declared graph — so a missing link is caught before a single request is ever served.\n\n:::muted\nTrade-off\n:::\nYou pay for this safety with upfront ceremony — every dependency crossing a boundary must be declared, even when it \"obviously\" should just work — nothing can be reached implicitly.\n\n:::muted\nCommon pitfall\n:::\nExposing everything by default to avoid the ceremony collapses the boundary entirely — once every module can reach into every other module's internals, the exports list stops meaning anything, and the fail-fast check has nothing left to check.\n\n:::muted\nGo deeper\n:::\ntwo modules end up needing each other's exports at the same time — what does that circular shape do to the startup graph, and what's the actual fix?","clozes":[{"n":1,"term":"explicit","distractors":["implicit","optional"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/0-module-1/11$t$, '231d8cc57', $t$0-fullstack-mastery/0-module-1$t$, 11, true, $t$middle$t$, NULL, $j${"vi":{"question":"Phần lớn service trong app nên mặc định là một instance dùng chung suốt vòng đời cả app. Khi nào cái mặc định đó sai, và bạn trả giá gì khi chuyển một service sang vòng đời theo-từng-request?","tags":["Architecture","Dependency Injection"]},"en":{"question":"Most services in your app should default to a single shared instance for the whole app's lifetime. When is that default wrong, and what do you pay when you switch a service to a per-request lifetime instead?","tags":["Architecture","Dependency Injection"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nCái mặc định đó sai ngay khi một service phải giữ state không bao giờ được rò rỉ giữa hai caller khác nhau — như tenant context theo từng request; chuyển nó sang vòng đời {{c1::theo-từng-request::theo-từng-session,theo-từng-tenant}} mua được sự cô lập đó, nhưng giờ bạn trả giá dựng lại từ đầu ở mỗi request thay vì đúng một lần cho cả vòng đời app.\n\n:::muted\nCơ chế\n:::\nMột instance theo-từng-request chạy lại constructor cho mỗi request tới, và chi phí dựng lại đó lan lên trên — bất cứ thứ gì phụ thuộc vào một service theo-từng-request cũng buộc phải trở thành theo-từng-request, vì một object sống lâu hơn không thể giữ tham chiếu tới một object sống ngắn hơn mà không gây lẫn lộn.\n\n:::muted\nTrade-off\n:::\nCô lập đổi lấy chi phí: dùng chung mãi mãi gần như miễn phí nhưng rò rỉ state giữa các caller nếu không cẩn thận; theo-từng-request an toàn nhưng nhân chi phí dựng lên và ép vòng đời đó lên mọi thứ phụ thuộc nó.\n\n:::muted\nBẫy thường gặp\n:::\nTiêm một service theo-từng-request vào một service sống suốt vòng đời app âm thầm giữ instance của request đầu tiên sống mãi mãi — mọi request sau âm thầm dùng lại state cũ thay vì có bản riêng của mình.\n\n:::muted\nĐào sâu tiếp\n:::\napp của bạn hiện chưa có service nào theo-từng-request — dấu hiệu đầu tiên nào, trong traffic production thật, mới thật sự đáng để bắt đầu dùng một cái?","clozes":[{"n":1,"term":"theo-từng-request","distractors":["theo-từng-session","theo-từng-tenant"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nThe default is wrong the moment a service must hold state that must never leak between two different callers — like per-request tenant context; switching it to a {{c1::per-request::per-session,per-tenant}} lifetime buys that isolation, but you now pay a fresh construction cost on every single request instead of once for the app's whole lifetime.\n\n:::muted\nHow it works\n:::\nA per-request instance re-runs its constructor for every incoming request, and that re-creation cost propagates upward — anything that depends on a per-request service must also become per-request, since a longer-lived object can't hold a reference to a shorter-lived one without confusion.\n\n:::muted\nTrade-off\n:::\nIsolation versus cost: shared-forever is nearly free but leaks state across callers if you're not careful; per-request is safe but multiplies construction work and forces the same lifetime onto its dependents.\n\n:::muted\nCommon pitfall\n:::\nInjecting a per-request service into a service that's meant to live for the whole app secretly keeps the first request's instance alive forever — every later request silently reuses stale state instead of getting its own.\n\n:::muted\nGo deeper\n:::\nyour app currently has zero per-request services — what's the first sign, in production traffic, that would actually justify introducing one?","clozes":[{"n":1,"term":"per-request","distractors":["per-session","per-tenant"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/0-module-1/12$t$, '231d8cc57', $t$0-fullstack-mastery/0-module-1$t$, 12, true, $t$senior$t$, NULL, $j${"vi":{"question":"Validation layer (pipe) của bạn chỉ bọc quanh HTTP request — nó không hề biết một queue consumer hay một WebSocket handler thậm chí tồn tại. Nếu đúng cùng một service method đó được gọi từ một message queue thay vì một HTTP request, sự bảo vệ nào âm thầm biến mất, và bạn xử lý thế nào?","tags":["Architecture","Validation"]},"en":{"question":"Your validation layer (pipe) only ever wraps HTTP requests — it has no idea a queue consumer or a WebSocket handler even exists. If the exact same service method gets called from a background queue message instead of an HTTP request, what protection silently disappears, and what do you do about it?","tags":["Architecture","Validation"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nNgay khi một service được gọi từ bất kỳ đâu khác ngoài đường HTTP — một message queue, một job theo lịch, một sự kiện WebSocket — validation layer {{c1::gắn với HTTP::gắn với database,độc lập framework}} không bao giờ chạy, nên đúng cùng một service method từng an toàn từ một entry point giờ nhận input hoàn toàn chưa kiểm tra từ entry point kia.\n\n:::muted\nCơ chế\n:::\nMột validation layer được gắn vào pipeline riêng của HTTP, buộc chặt vào cách transport đó đóng khung một request; một message từ queue hay socket không bao giờ đi vào pipeline đó, nên không gì chặn input sai dạng trước khi nó tới business method.\n\n:::muted\nTrade-off\n:::\nĐăng ký một validation/guard layer riêng cho mỗi transport cho mọi entry point sự bảo vệ thật, đổi lại phải nhân đôi (hoặc chia sẻ tường minh) logic validate ở từng nơi thay vì viết một lần.\n\n:::muted\nBẫy thường gặp\n:::\nGiả định \"dữ liệu này chắc chắn đã được validate vì API có validate\" ngay khi cùng business logic đó được tái sử dụng từ một entry point thứ hai — validation chưa bao giờ là thuộc tính của business method, chỉ là thuộc tính của đúng một pipeline nó tình cờ đứng sau.\n\n:::muted\nĐào sâu tiếp\n:::\nnếu bạn tách các rule validate thật ra thành một hàm thuần chia sẻ giữa cả HTTP pipe lẫn queue consumer, phần nào của cam kết an toàn bạn lấy lại được, và phần nào bạn vẫn phải tự nối tay ở từng entry point?","clozes":[{"n":1,"term":"gắn với HTTP","distractors":["gắn với database","độc lập framework"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nThe moment a service is called from anywhere other than the HTTP path — a queue message, a scheduled job, a WebSocket event — the {{c1::HTTP-bound::database-bound,framework-agnostic}} validation layer never runs at all, so the exact same service method that was safe from one entry point is now receiving completely unchecked input from the other.\n\n:::muted\nHow it works\n:::\nA validation layer is wired into the HTTP-specific pipeline, tied to how that one transport frames a request; a queue or socket message never enters that pipeline, so nothing rejects malformed input before it reaches the business method.\n\n:::muted\nTrade-off\n:::\nRegistering a dedicated validation/guard layer per transport gives every entry point real protection, at the cost of duplicating (or explicitly sharing) validation logic across each one instead of writing it once.\n\n:::muted\nCommon pitfall\n:::\nAssuming \"this data is already validated because the API validates it\" the moment the same business logic gets reused from a second entry point — the validation was never a property of the business method, only of the one pipeline it happened to sit behind.\n\n:::muted\nGo deeper\n:::\nif you extract the actual validation rules into a plain function shared by both the HTTP pipe and the queue consumer, what part of the safety guarantee do you get back, and what part do you still have to wire by hand at each entry point?","clozes":[{"n":1,"term":"HTTP-bound","distractors":["database-bound","framework-agnostic"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/0-module-1/13$t$, '231d8cc57', $t$0-fullstack-mastery/0-module-1$t$, 13, true, $t$middle$t$, NULL, $j${"vi":{"question":"Một interceptor bọc response cần đọc một timestamp mà một interceptor đo thời gian đã ghi trước đó trong cùng request. Các interceptor tháo ra theo thứ tự ngược (LIFO) ở chiều đi ra — vì sao sự đảo ngược đó quyết định việc cái bọc response có thật sự thấy được timestamp đó hay không?","tags":["Architecture","Request Lifecycle"]},"en":{"question":"A response-wrapping interceptor needs to read a timestamp that a timing interceptor set earlier in the same request. Interceptors unwind in reverse order on the way out (LIFO) — why does that reversal decide whether the wrapper can actually see that timestamp or not?","tags":["Architecture","Request Lifecycle"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nỞ chiều đi ra, logic \"after\" của interceptor nào chạy {{c1::cuối cùng::đầu tiên,song song}} chính là interceptor được đăng ký đầu tiên — nên nếu cái bọc response cần dữ liệu mà interceptor đo thời gian ghi ra, interceptor đo thời gian phải được đăng ký trước cái bọc, nghĩa là nó chạy bước \"after\" của nó muộn hơn và giá trị đã tồn tại lúc đó.\n\n:::muted\nCơ chế\n:::\nMỗi interceptor chạy code trước handler theo đúng thứ tự đăng ký, rồi tháo ra theo đúng thứ tự ngược lại sau khi handler trả về — nên cái đăng ký cuối cùng là cái chạy logic \"after\" đầu tiên, còn cái đăng ký đầu tiên chạy cuối cùng, cho nó cái nhìn tươi nhất về mọi thứ những cái khác đã ghi ra.\n\n:::muted\nTrade-off\n:::\nĐiều này cho phép bước \"after\" của bất kỳ interceptor nào dựa trên dữ liệu interceptor khác đã tạo ra, nhưng chỉ khi bạn đặt đúng thứ tự đăng ký — sự phụ thuộc đó hoàn toàn ngầm định, không gì trong type system ép buộc nó.\n\n:::muted\nBẫy thường gặp\n:::\nĐổi thứ tự đăng ký hai interceptor vì một lý do chẳng liên quan (như sắp xếp lại import theo abc) âm thầm phá vỡ một phụ thuộc mà code của cả hai interceptor không hề khai báo rõ ràng — bug chỉ lộ ra như một field bị thiếu hoặc cũ trong response.\n\n:::muted\nĐào sâu tiếp\n:::\ngiờ bạn có ba interceptor mà bước \"after\" của mỗi cái phụ thuộc vào cái trước nó — chuỗi đó thật ra nói lên điều gì về việc ba interceptor này đang làm một việc hay nên gộp thành một?","clozes":[{"n":1,"term":"cuối cùng","distractors":["đầu tiên","song song"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nOn the way out, whichever interceptor's \"after\" logic runs {{c1::last::first,in parallel}} is the one registered first — so if the wrapper needs data the timing interceptor wrote, the timing interceptor must be registered before the wrapper, meaning it runs its \"after\" step later and the value already exists by then.\n\n:::muted\nHow it works\n:::\nEach interceptor runs code before the handler in registration order, then unwinds in the exact reverse order after the handler returns — so the last one registered is the first one to run its \"after\" logic, and the first one registered is the last, giving it the freshest view of everything the others already wrote.\n\n:::muted\nTrade-off\n:::\nThis lets any interceptor's \"after\" step build on data other interceptors already produced, but only if you get the registration order right — the dependency is entirely implicit, nothing in the type system enforces it.\n\n:::muted\nCommon pitfall\n:::\nSwapping two interceptors' registration order for an unrelated reason (like alphabetizing imports) silently breaks a dependency neither interceptor's code visibly declares — the bug only shows up as a missing or stale field in the response.\n\n:::muted\nGo deeper\n:::\nyou now have three interceptors where each one's \"after\" step depends on the one before it — what does that chain actually tell you about whether these three interceptors are doing one job or should be merged into one?","clozes":[{"n":1,"term":"last","distractors":["first","in parallel"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/0-module-1/14$t$, '231d8cc57', $t$0-fullstack-mastery/0-module-1$t$, 14, true, $t$middle$t$, NULL, $j${"vi":{"question":"Hai nguồn config khác nhau cùng định nghĩa một key, và loader của bạn phải quyết định cái nào thắng. Vì sao \"loader có một rule precedence\" chưa đủ thông tin để debug an toàn một giá trị sai ở production — bạn cần biết thêm gì nữa?","tags":["Configuration","Precedence"]},"en":{"question":"Two different config sources both define the same key, and your loader has to decide which one wins. Why is \"the loader has a precedence rule\" not enough information to safely debug a wrong value in production — what else do you need to know?","tags":["Configuration","Precedence"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nBạn cần biết chính xác loader của mình cài mô hình precedence nào — một số chọn khớp {{c1::đầu tiên::cuối cùng,ưu tiên cao nhất}} rồi bỏ hẳn mọi nguồn sau, số khác merge mọi nguồn và để nguồn sau ghi đè từng field một, và hai mô hình đó cho ra người thắng ngược nhau từ đúng cùng một thứ tự file.\n\n:::muted\nCơ chế\n:::\nMột loader first-match-wins dừng tìm ngay khi thấy key, nên chỉ thứ tự nguồn mới quan trọng; một loader merge/override đọc mọi nguồn và ghi đè giá trị cũ bằng giá trị mới từng field một, nên một nguồn có thể thắng ở key này và thua ở key khác tùy nó thật sự định nghĩa gì.\n\n:::muted\nTrade-off\n:::\nFirst-match-wins dễ suy luận (một người thắng rõ ràng, không ghi đè nửa vời) nhưng được-ăn-cả-ngã-về-không theo từng file; merge/override cho phép bạn xếp một file nhỏ riêng-cho-profile lên trên một file base lớn, đổi lại giá trị cuối cùng của bất kỳ key nào khó truy về đúng một nguồn hơn.\n\n:::muted\nBẫy thường gặp\n:::\nGiả định mô hình của project hiện tại áp dụng luôn cho một project khác bạn đang debug — sắp lại thứ tự nguồn \"kiểu từng chạy trước đây\" chẳng làm gì cả (hoặc làm ngược lại điều bạn mong) nếu hai loader không chung mô hình precedence.\n\n:::muted\nĐào sâu tiếp\n:::\nloader của bạn âm thầm rơi về giá trị mặc định thay vì báo lỗi khi một key thiếu ở mọi nguồn — điều đó tương tác thế nào với việc debug precedence, và đó là lưới an toàn hay cái bẫy?","clozes":[{"n":1,"term":"đầu tiên","distractors":["cuối cùng","ưu tiên cao nhất"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nYou need to know exactly which precedence model your loader implements — some pick the {{c1::first::last,highest-priority}} match and ignore every later source outright, others merge every source and let the later one override field by field, and those two models produce opposite winners from the exact same file order.\n\n:::muted\nHow it works\n:::\nA first-match-wins loader stops looking the moment it finds the key, so only the order of sources matters; a merge/override loader reads every source and overwrites earlier values with later ones field by field, so a source can win on some keys and lose on others depending on what it actually defines.\n\n:::muted\nTrade-off\n:::\nFirst-match-wins is simple to reason about (one clear winner, no partial overrides) but all-or-nothing per file; merge/override lets you layer a small profile-specific file over a big base file, at the cost of the final value for any one key being harder to trace to a single source.\n\n:::muted\nCommon pitfall\n:::\nAssuming your current project's model transfers to a different one you're debugging — reordering sources \"the way it worked last time\" does nothing (or does the opposite of what you expect) if the two loaders don't share a precedence model.\n\n:::muted\nGo deeper\n:::\nyour loader silently falls back to a default value instead of erroring when a key is missing from every source — how does that interact with precedence debugging, and is it a safety net or a trap?","clozes":[{"n":1,"term":"first","distractors":["last","highest-priority"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/0-module-1/15$t$, '231d8cc57', $t$0-fullstack-mastery/0-module-1$t$, 15, true, $t$junior$t$, NULL, $j${"vi":{"question":"App của bạn vẫn boot thành công dù thiếu một biến config bắt buộc, và chỉ crash ở request thật đầu tiên cần tới nó. Vì sao điều đó tệ hơn từ chối boot luôn, và validate schema lúc khởi động thật sự tốn của bạn cái gì?","tags":["Configuration","Validation"]},"en":{"question":"Your app can boot successfully even with a required config variable missing, and only crash the first time a request actually needs it. Why is that worse than refusing to boot at all, and what does validating the schema at startup actually cost you?","tags":["Configuration","Validation"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nBoot thành công dù thiếu biến nghĩa là lỗi lộ ra ở thời điểm bất tiện nhất có thể — request thật đầu tiên tình cờ chạm tới nó, ở production, với một stack trace trông chẳng liên quan gì tới config — thay vì ngay lập tức và {{c1::ồn ào::âm thầm,muộn màng}} lúc deploy khi việc sửa còn rẻ.\n\n:::muted\nCơ chế\n:::\nValidate toàn bộ schema config đúng một lần lúc khởi động kiểm mọi biến bắt buộc từ đầu, trước khi app nhận bất kỳ traffic nào, nên một giá trị thiếu hay sai dạng làm fail chính cái deploy đó thay vì một request ngẫu nhiên nhiều giờ hay nhiều ngày sau.\n\n:::muted\nTrade-off\n:::\nCái giá là bạn phải khai báo đầy đủ hình dạng bắt buộc từ đầu và giữ nó đồng bộ khi config lớn lên — thêm chút thủ tục đầu vào đổi lấy việc không bao giờ phát hiện một biến thiếu qua một cuộc gọi báo động lúc 3 giờ sáng.\n\n:::muted\nBẫy thường gặp\n:::\nThêm một config key bắt buộc mới vào code mà không thêm vào schema — schema giờ âm thầm validate một thứ không đầy đủ, và lỗ hổng đó hành xử y hệt như không có validation nào cho đúng key đó.\n\n:::muted\nĐào sâu tiếp\n:::\nmột biến config là optional ở hầu hết môi trường nhưng bắt buộc chỉ ở production — bạn diễn đạt điều đó trong schema thế nào mà không bắt buộc nó khắp nơi lẫn không mất đi cam kết fail-fast ở chỗ nó thật sự quan trọng?","clozes":[{"n":1,"term":"ồn ào","distractors":["âm thầm","muộn màng"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nBooting successfully with a missing variable means the failure surfaces at the least convenient possible moment — the first real request that happens to touch it, in production, with a stack trace that looks unrelated to config — instead of immediately and {{c1::loudly::silently,eventually}} at deploy time when it's cheap to fix.\n\n:::muted\nHow it works\n:::\nValidating the whole config schema once at startup checks every required variable up front, before the app accepts any traffic, so a missing or malformed value fails the deploy itself rather than a random request hours or days later.\n\n:::muted\nTrade-off\n:::\nThe cost is you must declare the full required shape up front and keep it in sync as config grows — a little more upfront ceremony in exchange for never discovering a missing variable from a page at 3am.\n\n:::muted\nCommon pitfall\n:::\nAdding a new required config key to the code without adding it to the schema — the schema now silently validates something incomplete, and the gap behaves exactly like having no validation at all for that one key.\n\n:::muted\nGo deeper\n:::\na config variable is optional for most environments but required in production only — how do you express that in a schema without either over-requiring it everywhere or losing the fail-fast guarantee where it actually matters?","clozes":[{"n":1,"term":"loudly","distractors":["silently","eventually"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/0-module-1/16$t$, '231d8cc57', $t$0-fullstack-mastery/0-module-1$t$, 16, true, $t$middle$t$, NULL, $j${"vi":{"question":"Bạn cố tình gửi đúng cùng một log event xuống hai pipeline khác nhau cùng lúc — một render thành text có màu cho console của dev, một thành JSON thuần cho một file mà máy sẽ parse. Vì sao giữ cả hai thay vì chỉ chọn cái nào hữu ích hơn?","tags":["Observability","Logging"]},"en":{"question":"You deliberately send the exact same log event down two different pipelines at once — one rendered as colored text for a developer's console, one as plain JSON for a file a machine will parse. Why keep both instead of just picking whichever one is more useful?","tags":["Observability","Logging"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nMột người đọc console sống và một máy đang index một file muốn những thứ ngược nhau từ cùng một event, nên phân tán nó ra {{c1::nhiều::một sink dùng chung,nén lại}} sink — mỗi cái với format riêng — thỏa mãn cả hai mà không phải log event hai lần hay ép một bên chịu format của bên kia.\n\n:::muted\nCơ chế\n:::\nLogger giữ một danh sách transport và đẩy mọi event tới tất cả; mỗi transport áp format riêng của nó độc lập, nên cùng dữ liệu gốc có thể render thành text màu dễ đọc ở một nơi và JSON nghiêm ngặt máy-parse-được ở nơi khác.\n\n:::muted\nTrade-off\n:::\nNhiều transport hơn nghĩa là nhiều I/O và nhiều format phải bảo trì hơn, nhưng đó là cái giá của việc không phải chọn giữa \"dễ đọc cho người\" và \"query được cho máy\" — chỉ chọn một sẽ làm việc còn lại mãi mãi khó hơn.\n\n:::muted\nBẫy thường gặp\n:::\nÁp luôn format đẹp, có màu cho cả sink file hay aggregator — aggregator không parse được mã màu và khoảng trắng tự do, nên cái \"tiện lợi\" của một format dùng chung âm thầm phá mọi query và alert phía sau.\n\n:::muted\nĐào sâu tiếp\n:::\nbạn thêm một sink thứ ba gửi log tới một dịch vụ cảnh báo thời gian thực — sink đó có cần một format thứ ba riêng, hay có thể dùng lại một trong hai cái đã có, và điều gì quyết định việc đó?","clozes":[{"n":1,"term":"nhiều","distractors":["một sink dùng chung","nén lại"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nA human reading a live console and a machine indexing a file want opposite things from the same event, so fanning it out to {{c1::multiple::one shared,compressed}} sinks — each with its own format — satisfies both without logging the event twice or forcing one reader to suffer the other's format.\n\n:::muted\nHow it works\n:::\nThe logger holds a list of transports and pushes every event to all of them; each transport applies its own format independently, so the same underlying data can render as readable colored text in one place and strict machine-parseable JSON in another.\n\n:::muted\nTrade-off\n:::\nMore transports means more I/O and more formats to maintain, but that's the price of not choosing between \"readable for humans\" and \"queryable for machines\" — picking only one would make the other job permanently harder.\n\n:::muted\nCommon pitfall\n:::\nApplying the pretty, colored format to the file or aggregator sink too — the aggregator can't parse color codes and free-form spacing, so the \"convenience\" of one shared format quietly breaks every downstream query and alert.\n\n:::muted\nGo deeper\n:::\nyou add a third sink that ships logs to a real-time alerting service — does that sink need its own third format, or can it reuse one of the existing two, and what decides that?","clozes":[{"n":1,"term":"multiple","distractors":["one shared","compressed"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/0-module-1/17$t$, '231d8cc57', $t$0-fullstack-mastery/0-module-1$t$, 17, true, $t$senior$t$, NULL, $j${"vi":{"question":"Sink file-transport của bạn gặp một filesystem read-only hoặc đầy ổ đĩa và throw. Điều đó nên crash toàn bộ ứng dụng, hay logging nên xuống cấp một cách nhẹ nhàng thay vào đó — và vì sao câu trả lời lại quan trọng đến vậy cho một mảnh hạ tầng vốn chỉ để quan sát?","tags":["Observability","Resilience"]},"en":{"question":"Your file-transport sink hits a read-only filesystem or a full disk and throws. Should that crash your entire application, or should logging degrade gracefully instead — and why does the answer matter so much for a piece of infrastructure that's supposed to be purely observational?","tags":["Observability","Resilience"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nLogging tồn tại để giúp bạn thấy chuyện gì đang xảy ra — nó không bao giờ nên trở thành thứ {{c1::hạ gục::làm chậm,âm thầm bỏ qua}} chính app nó đang quan sát, nên một sink hỏng nên bị bắt và xuống cấp (rơi về một sink khác, hoặc bỏ log đó) thay vì lan ra thành một exception không bắt được làm sập cả process.\n\n:::muted\nCơ chế\n:::\nXử lý lỗi riêng của logger bọc quanh từng transport nên một lỗi ở một sink — ổ đĩa đầy, một trục trặc mạng tới aggregator từ xa — bị bắt và khoanh vùng ngay đó, để phần còn lại của app (và bất kỳ sink nào khác vẫn hoạt động) tiếp tục chạy bình thường.\n\n:::muted\nTrade-off\n:::\nXuống cấp nhẹ nhàng nghĩa là bạn có thể âm thầm mất vài log trong lúc một sink gặp sự cố, đánh đổi khả năng quan sát hoàn hảo lấy cam kết mạnh hơn nhiều rằng code quan sát không bao giờ được làm sập service nó đang theo dõi.\n\n:::muted\nBẫy thường gặp\n:::\nGiữ nguyên hành vi mặc định \"crash khi transport lỗi\" vì nó chưa bao giờ xảy ra lúc dev — lần đầu nó thật sự quan trọng là ở production, khi một ổ đĩa đầy và kéo sập cả app đúng lúc tệ nhất.\n\n:::muted\nĐào sâu tiếp\n:::\nnếu logging có thể âm thầm mất event trong lúc một sink gặp sự cố, cơ chế thật sự nào cho bạn biết lỗ hổng đó đã xảy ra, thay vì chỉ tin vào những log đã lọt qua được?","clozes":[{"n":1,"term":"hạ gục","distractors":["làm chậm","âm thầm bỏ qua"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nLogging exists to help you see what's happening — it should never become the thing that {{c1::takes down::slows down,silently ignores}} the app it's supposed to be observing, so a failing sink should be caught and degrade (fall back to another sink, or drop the log) rather than propagate as an unhandled exception that crashes the process.\n\n:::muted\nHow it works\n:::\nThe logger's own error handling wraps each transport so a failure in one sink — a full disk, a network blip to a remote aggregator — is caught and contained there, letting the rest of the app (and any other still-working sinks) keep running normally.\n\n:::muted\nTrade-off\n:::\nGraceful degradation means you might silently lose some logs during an outage of one sink, which trades perfect observability for the much stronger guarantee that observability code can never crash the service it's watching.\n\n:::muted\nCommon pitfall\n:::\nLeaving the default \"crash on transport error\" behavior in place because it never came up in development — the first time it actually matters is in production, when a disk fills up and takes the whole app down with it, at the worst possible moment.\n\n:::muted\nGo deeper\n:::\nif logging can silently drop events during a sink outage, what's the actual mechanism that lets you notice the gap happened at all, instead of just trusting the logs that did make it through?","clozes":[{"n":1,"term":"takes down","distractors":["slows down","silently ignores"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/0-module-1/18$t$, '231d8cc57', $t$0-fullstack-mastery/0-module-1$t$, 18, true, $t$middle$t$, NULL, $j${"vi":{"question":"Mọi error response API của bạn trả về đều dùng đúng một khuôn envelope, dù các lỗi bên dưới hoàn toàn khác nhau. Vì sao field path và timestamp lại quan trọng, trong khi cả hai chẳng nói cho client biết chuyện gì thật sự đã sai?","tags":["Error Handling","API Design"]},"en":{"question":"Every error response your API sends back uses the exact same envelope shape, even though the underlying errors are completely different. Why do the path and timestamp fields matter, given that neither one tells the client anything about what actually went wrong?","tags":["Error Handling","API Design"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nPath và timestamp không phải để client hiểu lỗi — chúng để {{c1::đối chiếu::xác thực,giới hạn tốc độ}} một báo lỗi từ client với đúng dòng log tương ứng trên server, biến một câu mơ hồ \"API trả về lỗi\" thành một sự cố có thể truy vết thật sự.\n\n:::muted\nCơ chế\n:::\nKhi có gì sai, người debug có thể lấy path và timestamp (cộng thêm một request id nếu có) đi thẳng tới log server và tìm đúng request đã fail, cùng với bất kỳ thứ gì log phía server đã ghi mà client chưa bao giờ thấy.\n\n:::muted\nTrade-off\n:::\nMột khuôn envelope cố định duy nhất nghĩa là mọi client có thể viết đúng một đường xử lý lỗi thay vì đoán khuôn theo từng endpoint, nhưng cũng nghĩa là bạn không bao giờ được lén thêm field ad-hoc riêng cho một loại lỗi mà không phá vỡ sự nhất quán đó.\n\n:::muted\nBẫy thường gặp\n:::\nCoi path và timestamp là trang trí tùy chọn rồi bỏ chúng khỏi một số error response \"vì client không cần\" — client chưa bao giờ cần chúng, nhưng người debug sự cố thì cần tuyệt đối.\n\n:::muted\nĐào sâu tiếp\n:::\nhai user hoàn toàn khác nhau chạm cùng một endpoint và nhận đúng cùng một message lỗi ở gần như cùng một timestamp — field nào đang thiếu trong envelope này mà nếu có sẽ cho bạn phân biệt được hai sự cố của họ?","clozes":[{"n":1,"term":"đối chiếu","distractors":["xác thực","giới hạn tốc độ"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nPath and timestamp aren't for the client to understand the error — they're for {{c1::correlating::authenticating,rate-limiting}} a client's bug report with the exact matching line in your server logs, turning a vague \"the API returned an error\" into a traceable incident you can actually investigate.\n\n:::muted\nHow it works\n:::\nWhen something goes wrong, whoever's debugging it can take the path and timestamp (plus a request id, if you have one) straight to the server logs and find the exact request that failed, alongside whatever the server-side log recorded that the client never saw.\n\n:::muted\nTrade-off\n:::\nA single fixed envelope shape means every client can write one error-handling code path instead of guessing the shape per endpoint, but it also means you can never sneak extra ad-hoc fields onto just one error type without breaking that consistency.\n\n:::muted\nCommon pitfall\n:::\nTreating path and timestamp as optional decoration and dropping them from certain error responses \"since the client doesn't need them\" — the client never needed them, but whoever's debugging the incident absolutely does.\n\n:::muted\nGo deeper\n:::\ntwo completely different users hit the exact same endpoint and get the exact same error message at nearly the same timestamp — what's the one field missing from this envelope that would let you tell their two incidents apart?","clozes":[{"n":1,"term":"correlating","distractors":["authenticating","rate-limiting"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/0-module-1/19$t$, '231d8cc57', $t$0-fullstack-mastery/0-module-1$t$, 19, true, $t$senior$t$, NULL, $j${"vi":{"question":"Một lỗi xảy ra giữa lúc đang stream một file lớn về cho client — sau khi bạn đã bắt đầu ghi response body với status 200. Global error handler của bạn cố set status 500 và ghi khuôn error envelope thông thường. Chuyện gì thật sự xảy ra, và vì sao bạn không thể xử lý lỗi này theo cách bình thường?","tags":["Error Handling","Streaming"]},"en":{"question":"An error happens in the middle of streaming a large file back to the client — after you've already started writing the response body with a 200 status. Your global error handler tries to set a 500 status code and write its usual error envelope. What actually happens, and why can't you just handle this error the normal way?","tags":["Error Handling","Streaming"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nMột khi response header (bao gồm status code) đã được gửi cho client, chúng bị {{c1::khoá::được buffer,có thể renegotiate}} — cố set một status code khác lúc đó không làm gì cả hoặc throw, vì client đã được báo \"200, body sắp tới\" và lời hứa đó không thể rút lại.\n\n:::muted\nCơ chế\n:::\nHTTP gửi header trước, rồi mới tới body; ngay khi chunk đầu tiên của body đi ra, status code đã chốt, nên một error handler thông thường vẫn kỳ vọng còn kiểm soát được status code đang làm việc trên một giả định sai cho bất cứ thứ gì đã giữa-stream.\n\n:::muted\nTrade-off\n:::\nLựa chọn thật sự duy nhất khi đã giữa-stream là ngắt kết nối đột ngột (client thấy một response bị cắt cụt, hỏng) hoặc phát ra tín hiệu lỗi trong-band ngay trong chính stream đó — không cái nào sạch bằng một error response bình thường, vì con đường sạch đã tiêu ở byte đầu tiên rồi.\n\n:::muted\nBẫy thường gặp\n:::\nViết code xử lý lỗi chung cố set status và ghi envelope JSON vô điều kiện, mà không bao giờ kiểm tra xem response đã bắt đầu gửi chưa — nó chạy đúng cho mọi request thông thường và fail âm thầm (hoặc throw một lỗi thứ hai còn rối hơn) cho bất cứ thứ gì đang stream.\n\n:::muted\nĐào sâu tiếp\n:::\nbiết rằng bạn không thể sửa status code sau khi stream bắt đầu, bạn sẽ kiểm tra gì trước cả khi bắt đầu stream để việc fail giữa-stream hiếm xảy ra nhất có thể?","clozes":[{"n":1,"term":"khoá","distractors":["được buffer","có thể renegotiate"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nOnce the response headers (including the status code) have already been sent to the client, they're {{c1::locked::buffered,renegotiable}} — trying to set a different status code at that point does nothing or throws, because the client has already been told \"200, here comes a body\" and that promise can't be taken back.\n\n:::muted\nHow it works\n:::\nHTTP sends headers first, then the body; the moment the first chunk of body goes out, the status code is committed, so a normal error handler that expects to still control the status code is working with a false assumption for anything already mid-stream.\n\n:::muted\nTrade-off\n:::\nThe only real options once you're mid-stream are to end the connection abruptly (the client sees a truncated, corrupted response) or emit some in-band error signal inside the stream itself — neither is as clean as a normal error response, because the clean path was already spent on the first byte.\n\n:::muted\nCommon pitfall\n:::\nWriting generic error-handling code that unconditionally tries to set a status and write a JSON envelope, without ever checking whether the response has already started — it works for every ordinary request and fails silently (or throws a second, more confusing error) for anything streaming.\n\n:::muted\nGo deeper\n:::\nknowing you can't fix the status code after streaming starts, what would you check for before you even begin the stream to make failing mid-stream as rare as possible?","clozes":[{"n":1,"term":"locked","distractors":["buffered","renegotiable"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_decks (deck_id, course, sort_index, live_version, difficulty, titles, descriptions, module_refs, tracks, card_count, free_card_count, updated_at) VALUES ($t$0-fullstack-mastery/0-module-1$t$, $t$0-fullstack-mastery$t$, 0, '231d8cc57', $t$hard$t$, $j${"vi":"Module 1: Nền tảng Backend","en":"Module 1: Backend Foundations"}$j$::jsonb, $j${"vi":"Câu hỏi phỏng vấn về những ý tưởng nền tảng của mọi backend framework — inversion of control, thứ tự tầng cố định của request pipeline, tách config khỏi code, structured logging, và chuẩn hoá lỗi về một điểm. Bám sát ví dụ thật trong lesson qua nhiều ngôn ngữ, không gắn cứng vào 1 framework.","en":"Interview questions on the ideas every backend framework is built on — inversion of control, the request pipeline's fixed layer order, separating config from code, structured logging, and normalizing errors at one point. Grounded in the lesson's own worked examples across languages, not tied to one framework."}$j$::jsonb, $j$["nestjs-core-and-request-lifecycle"]$j$::jsonb, $j$["backend-fullstack","ai-engineer","founder"]$j$::jsonb, 20, 3, now()) ON CONFLICT (deck_id) DO NOTHING;
INSERT INTO review_deck_versions (deck_id, version, content_hash, source_hashes, imported_at) VALUES ($t$0-fullstack-mastery/1-api-design-and-graphql$t$, '231d8cc57', $t$3aaab0cc53f7b3c63b14de77f8dfa94872456f0bd12a244a4d31ffd67e3b842c$t$, $j${"cards/0-card/en.md":"86e00c70bf3d2f806b48900ce632b45c30613ab1187ebd9d389dd1c8829e0530","cards/0-card/vi.md":"edce7dba3cc3ac4e369633b90529f7e1ee9cd461c8b5c558c356acbba2ed798c","cards/1-card/en.md":"d4aa07aa4f1a50d83df889573644a4b47e2d345bdfa79427a1a08504e26cd5c8","cards/1-card/vi.md":"71d1816e7401cdef5f3e9fae81a0589e9da6e03847c3c58ebdc5348157857961","cards/10-card/en.md":"676e86d42b11c2832660f3eeb3352b39b16d6c6e674921ae846f015eb2ac2aaa","cards/10-card/vi.md":"db9c37c0f1143ed606f109ad8de90b4e5def9aa3ed8f7385d7bc9ae157208484","cards/11-card/en.md":"54148ff57876288ba3c222ce5255fdc2dffc1b468cef20b70332e5e8668a3adf","cards/11-card/vi.md":"129e1b6e0de30477dd77895de9b3277c802646e482a6c6de2092b420543aa919","cards/12-card/en.md":"829bc99c5ac5f1a9d71ab63c50aa639416bcc3f5eba166c3da1505d068c5be87","cards/12-card/vi.md":"e421223d65aacc983fca8a49d16b5409043b9b77195de6f44023cdd105b13aeb","cards/13-card/en.md":"3212ac8c4c9ae29e7e865c9775828ec6c086553be41385453f7fc44fb11cbeb9","cards/13-card/vi.md":"47f7041b3e2627d38497ae9cdebdc65a96a0bdc4d23161fdac3dc2e0ba105be1","cards/14-card/en.md":"1c73ca8bae425798d5afce3ec7b5f3ddac530e5ecb55d559f15c650cc1943427","cards/14-card/vi.md":"3d1c72f7d0ad0098cfc56615db0b428984589b52e85ea914190a182d4aaa3fe8","cards/15-card/en.md":"64782c7ec21ee1fed557edb360ad679641b2f8ebcfa22763bc1fb808033455ea","cards/15-card/vi.md":"8de7f14d4b204c3588950589146475e0d06104244c870c6bcf9d0e809470590e","cards/16-card/en.md":"1bb8e33814aba3677d453aca41e709863d69b2002a612eb6b04b25d2b4cc2e01","cards/16-card/vi.md":"d7ef8e135c17aa5a3380d04f4e07dfd8c315e459b09103b3df7495be04a80753","cards/17-card/en.md":"2b4cfa07c164912944c31b44b4edf18a2ab9808a8ede62658fbd71a00fcd7c8b","cards/17-card/vi.md":"96c9dcc689ddf04466acecd7997118782a469f63470f19635d8250160d22d013","cards/18-card/en.md":"ee10386c2a806bd1117b078b02b78f76f53766609b97fe1a8fce28030a0c57c9","cards/18-card/vi.md":"f8b3b349112ab59643b4d8adf8b523b6f56d595cb0a526f406eccc9de4e48966","cards/19-card/en.md":"6e5cf1f19288058307a28fd8a260e3790d3a33de2f2afcdec028b5fcd36be9bc","cards/19-card/vi.md":"c0192b92f44d804ba0d4d5d3c7faf57c1fc22e0b5566081a9d9954bf53e444f2","cards/2-card/en.md":"a1a13c5137ab1a8b54fd64e154d0bb688fca60b5289367dc11a23fa6dbe9c9f9","cards/2-card/vi.md":"eaa840d371bf357718e3b09b97f69bd24f45c4a983f7d66b1b9d01a061b9f592","cards/3-card/en.md":"73f45b0e12794c088505ee37ae73d6b9991f497e1d096171148f9191a4beb174","cards/3-card/vi.md":"f48aafd78190e0dbcfd8fb690d3cc43c8a467f87b022a2dee1b4a05ba33a4105","cards/4-card/en.md":"e559395a585eda47224587e01ae025ca6e70a649d124f9bdd3db0a16fbd49a59","cards/4-card/vi.md":"4b876e51dc72bb267cd36129d26801d38a225623adca14293f4468b1719f9696","cards/5-card/en.md":"de4592929c0f1610a8953db3ab4c0bd0ad2b06b37120a29ec0441aa15109ce56","cards/5-card/vi.md":"c5037394cba5c06de50dc176727a5433a553d767366daf96f6d57a312f4360e2","cards/6-card/en.md":"35faba4c1209b87c616277e0c9779373358c21a975d17a00a32ee617c4d50e7c","cards/6-card/vi.md":"f08f616350e82a1c3d3980f01ff956a71a762b75b3d492c9256ad3f3df206907","cards/7-card/en.md":"e4f47f91cb261e697d0b8421cbee54322435497c3b98ffc80e84e5f1d9ff0d6a","cards/7-card/vi.md":"7496987d5bb2740defc0f1ef740078f440f6494ec2657adb79661437241039b4","cards/8-card/en.md":"95b4dea168e738526257f4838316b6c5104b2a7c97dffbb2fef6a77ddefb9e87","cards/8-card/vi.md":"e700f550c5ca725ee86f5896c7b501500ed5e456ffe5160a9b0fd10f551d9b86","cards/9-card/en.md":"5fb3f72697c935226674629fb23da555fc466bee519031fa1653089822fee2c0","cards/9-card/vi.md":"b84d65f94d36015cb8bca6351e10aabf34d1a129b19bfdd216ad0d758bc35df9","en.md":"e8d0c30384626d1f31e40f4ffc7cdba098ddcb1463396c2ece3682ac59ded0d2","vi.md":"8c97290e3e6b54c1e00fe3c830b4072fe7350a6f729a26bfce9e525688a473ec"}$j$::jsonb, now()) ON CONFLICT (deck_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/1-api-design-and-graphql/0$t$, '231d8cc57', $t$0-fullstack-mastery/1-api-design-and-graphql$t$, 0, false, $t$junior$t$, NULL, $j${"vi":{"question":"Một đồng nghiệp expose mọi thứ qua POST /createUser, POST /getUser, POST /deleteUser rồi bảo \"server hiểu được là ổn rồi.\" Việc dồn hết mọi operation vào POST thực sự đánh mất điều gì?","tags":["HTTP Semantics","REST"]},"en":{"question":"A coworker exposes everything as POST /createUser, POST /getUser, POST /deleteUser and says \"the server understands it, so it's fine.\" What does collapsing every operation onto POST actually throw away?","tags":["HTTP Semantics","REST"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nDồn hết operation vào POST làm mất đi {{c1::HTTP method::URL path,request body}} như một tín hiệu — router, cache và proxy vốn đọc verb để phân biệt một lượt đọc an toàn với một lượt ghi, và không bên nào còn làm được điều đó khi mọi request trông giống hệt nhau trên đường truyền.\n\n:::muted\nCơ chế\n:::\nMột GET được hiểu ngầm là an toàn và cache được, một DELETE được hiểu là xoá, chỉ dựa vào tên method, không bên nào cần mở request body ra xem. Dồn mọi operation qua POST thì tín hiệu đó biến mất; cách duy nhất để biết endpoint làm gì là tự đọc URL riêng hoặc cấu trúc body.\n\n:::muted\nBẫy thường gặp\n:::\nTeam mất luôn khả năng cache miễn phí, retry an toàn tự động, và khả năng để bất kỳ thành phần trung gian nào phân biệt đọc với ghi — một CDN hay load balancer đứng trước API không còn ra được quyết định định tuyến nào nếu không tự parse từng request body.\n\n:::muted\nĐào sâu tiếp\n:::\ntrong các method đó, method nào một proxy có thể retry mù mà vẫn an toàn, và vì sao?","clozes":[{"n":1,"term":"HTTP method","distractors":["URL path","request body"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nCollapsing every operation onto POST throws away {{c1::the HTTP method::the URL path,the request body}} as a signal — routers, caches, and proxies read the verb to tell a safe read apart from a write, and none of them can do that anymore once every request looks identical on the wire.\n\n:::muted\nHow it works\n:::\nA GET is understood to be safe and cacheable, a DELETE is understood to mean removal, purely from the method name, without any party needing to open the request body. Route every operation through POST and that signal disappears; the only way to know what an endpoint does is to read its custom URL or body shape by hand.\n\n:::muted\nCommon pitfall\n:::\nThe team loses free caching, safe automatic retries, and the ability for any intermediary to distinguish a read from a write — a CDN or load balancer sitting in front of the API can no longer make a single routing decision without parsing every request body itself.\n\n:::muted\nGo deeper\n:::\nwhich of those methods can a proxy safely retry blindly, and why?","clozes":[{"n":1,"term":"the HTTP method","distractors":["the URL path","the request body"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/1-api-design-and-graphql/1$t$, '231d8cc57', $t$0-fullstack-mastery/1-api-design-and-graphql$t$, 1, false, $t$junior$t$, NULL, $j${"vi":{"question":"Một API trả về 200 khi tạo mới thành công VÀ cũng trả về 200 khi lookup thất bại. Vì sao đó là bug, và mỗi trường hợp nên trả về gì?","tags":["Status Codes","REST"]},"en":{"question":"One API returns 200 for a successful create AND 200 when a lookup fails. Why is that a bug, and what should each return?","tags":["Status Codes","REST"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nMột lượt tạo thành công nên trả về {{c1::status 201 Created::status 200 OK,status 202 Accepted}}, chứ không phải cùng mã 200 mà một lượt lookup thất bại đang dùng — dùng chung một mã cho cả hai nghĩa là client không còn phân biệt được thành công với thất bại nếu không mở body ra đọc.\n\n:::muted\nCơ chế\n:::\n201 thông báo một resource mới vừa được tạo ra, thường kèm header Location trỏ tới nó; một lookup thất bại nên trả về một status lỗi thật sự thay vì 200, để kết quả nhìn thấy được ngay từ dòng status, trước cả khi đọc body.\n\n:::muted\nBẫy thường gặp\n:::\nTrả 200 cho mọi thứ buộc mọi client phải soi body mới biết chuyện gì thực sự xảy ra, biến một phép kiểm tra status một dòng thành logic parse thủ công lặp lại ở từng nơi gọi.\n\n:::muted\nĐào sâu tiếp\n:::\nkhi lỗi là do phía server chứ không phải phía client, mã trả về có đổi không?","clozes":[{"n":1,"term":"status 201 Created","distractors":["status 200 OK","status 202 Accepted"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nA successful create should answer with {{c1::the 201 Created status::the 200 OK status,the 202 Accepted status}}, not the same 200 a failed lookup uses — reusing one code for both means the client can no longer tell success from failure without opening and parsing the body.\n\n:::muted\nHow it works\n:::\n201 announces that a new resource now exists, usually with a Location header pointing at it; a failed lookup should answer with an actual error status instead of 200, so the outcome is visible from the status line alone, before the body is even read.\n\n:::muted\nCommon pitfall\n:::\nReturning 200 for everything forces every client to sniff the body to know what actually happened, turning a one-line status check into custom parsing logic repeated at every call site.\n\n:::muted\nGo deeper\n:::\nwhen the failure is your server's fault instead of the client's, does the code change?","clozes":[{"n":1,"term":"the 201 Created status","distractors":["the 200 OK status","the 202 Accepted status"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/1-api-design-and-graphql/2$t$, '231d8cc57', $t$0-fullstack-mastery/1-api-design-and-graphql$t$, 2, false, $t$junior$t$, NULL, $j${"vi":{"question":"GET /users trả về danh sách rỗng khi không có gì khớp. Một đồng nghiệp cũng trả cùng body 200 rỗng đó cho GET /users/999 khi id 999 không tồn tại. Vậy có đúng không?","tags":["Status Codes","REST"]},"en":{"question":"GET /users returns an empty list when nothing matches. A teammate returns the same 200 empty body for GET /users/999 where the id doesn't exist. Is that right?","tags":["Status Codes","REST"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nKhông — một resource cụ thể được định danh mà không tồn tại nên trả về {{c1::status 404 Not Found::status 204 No Content,status 200 OK}}, còn một collection rỗng khớp với bộ lọc vẫn là một 200 hoàn toàn hợp lệ với danh sách rỗng.\n\n:::muted\nCơ chế\n:::\nHình dạng URL cho biết áp dụng quy tắc nào: endpoint collection mô tả một tập hợp, nên khớp 0 phần tử vẫn chỉ là một tập nhỏ và vẫn 200; endpoint single-resource định danh đúng một thứ cụ thể, nên việc nó không tồn tại là một tình huống not-found thật sự.\n\n:::muted\nBẫy thường gặp\n:::\nTrả 200 với body rỗng cho một resource cụ thể không tồn tại che giấu một vấn đề thật — client gửi id sai hoặc cũ — đằng sau một response trông giống hệt một kết quả rỗng có chủ đích và thành công.","clozes":[{"n":1,"term":"status 404 Not Found","distractors":["status 204 No Content","status 200 OK"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nNo — a single identified resource that doesn't exist should answer with {{c1::the 404 Not Found status::the 204 No Content status,the 200 OK status}}, while an empty collection matching a filter is still a perfectly valid 200 with an empty list.\n\n:::muted\nHow it works\n:::\nThe URL shape tells you which rule applies: a collection endpoint describes a set, so zero matches is just a small set and still 200; a single-resource endpoint names one specific thing, so its absence is a genuine not-found condition.\n\n:::muted\nCommon pitfall\n:::\nReturning 200 with an empty body for a missing single resource hides a real problem — the client sent a wrong or stale id — behind a response that looks identical to a successful, deliberately empty result.","clozes":[{"n":1,"term":"the 404 Not Found status","distractors":["the 204 No Content status","the 200 OK status"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/1-api-design-and-graphql/3$t$, '231d8cc57', $t$0-fullstack-mastery/1-api-design-and-graphql$t$, 3, true, $t$junior$t$, NULL, $j${"vi":{"question":"Bạn chỉ cần đổi email của một user. Vì sao việc dùng PUT hay PATCH lại quan trọng, và điều gì hỏng nếu PUT âm thầm giữ nguyên những field bạn không gửi?","tags":["HTTP Semantics","REST"]},"en":{"question":"You need to change only a user's email. Why does it matter whether you use PUT or PATCH, and what breaks if PUT quietly keeps the fields you didn't send?","tags":["HTTP Semantics","REST"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nPUT nghĩa là {{c1::thay thế toàn bộ::cập nhật một phần,merge}} resource — field nào bạn không gửi coi như phải biến mất hoặc reset — còn PATCH nghĩa là chỉ những field bạn gửi mới bị đụng tới; một handler PUT âm thầm giữ nguyên giá trị cũ cho field vắng mặt đã không còn tuân theo chính contract của nó.\n\n:::muted\nCơ chế\n:::\nMột handler PUT đúng coi payload là toàn bộ representation mới và ghi đúng y như vậy; một handler PATCH đúng đọc bản ghi hiện có rồi merge chỉ những field gửi lên vào trên đó trước khi ghi.\n\n:::muted\nBẫy thường gặp\n:::\nMột implementation PUT quay về giá trị cũ mỗi khi thiếu field đã âm thầm biến thành PATCH — client dựa vào cam kết \"thay thế\" của PUT để xoá một field sẽ thấy giá trị cũ vẫn còn đó, không nhúc nhích.","clozes":[{"n":1,"term":"thay thế toàn bộ","distractors":["cập nhật một phần","merge"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nPUT means {{c1::full replacement::partial update,merge}} of the resource — any field you don't send is supposed to disappear or reset — while PATCH means only the fields you send get touched; a PUT handler that quietly preserves old values for missing fields is no longer honoring its own contract.\n\n:::muted\nHow it works\n:::\nA correct PUT handler takes the payload as the entire new representation and writes exactly that; a correct PATCH handler reads the existing record and merges only the incoming fields on top of it before writing.\n\n:::muted\nCommon pitfall\n:::\nA PUT implementation that falls back to the old value whenever a field is absent has secretly turned into a PATCH — clients relying on PUT's replace guarantee to clear a field will find the old value stubbornly still there.","clozes":[{"n":1,"term":"full replacement","distractors":["partial update","merge"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/1-api-design-and-graphql/4$t$, '231d8cc57', $t$0-fullstack-mastery/1-api-design-and-graphql$t$, 4, true, $t$junior$t$, NULL, $j${"vi":{"question":"Một dev validate request data bằng các if-check rải rác bên trong service. Vì sao nên chuyển validation ra biên (boundary), trước khi bất kỳ business logic nào chạy?","tags":["Validation","API Design"]},"en":{"question":"A dev validates request data with scattered if-checks inside the service. Why move validation to the boundary instead, before any business logic runs?","tags":["Validation","API Design"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nChuyển validation ra {{c1::biên::tầng service,tầng database}} để input sai bị chặn ở đúng một chỗ, trước khi chạm tới business logic, thay vì bị kiểm tra rải rác ở bất cứ đâu một dev nhớ ra để thêm if-check.\n\n:::muted\nCơ chế\n:::\nMột DTO đi kèm bước validation ngay tại điểm vào kiểm tra toàn bộ hình dạng request ngay từ đầu và trả về danh sách lỗi rõ ràng ngay lập tức nếu có gì sai; chỉ request đã qua được mới được đưa xuống service.\n\n:::muted\nBẫy thường gặp\n:::\nCác if-check rải rác bên trong service dễ lệch nhau theo thời gian, bỏ sót edge case mà không ai nhớ kiểm tra lại ở từng nơi gọi, và để lọt dữ liệu sai qua bất kỳ đường nào bị quên kiểm tra.\n\n:::muted\nĐào sâu tiếp\n:::\ncòn những field thừa mà client không được phép gửi, như isAdmin, thì sao?","clozes":[{"n":1,"term":"biên","distractors":["tầng service","tầng database"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nMove validation to {{c1::the boundary::the service layer,the database layer}} so bad input gets rejected in one place, before it ever reaches business logic, instead of being checked piecemeal wherever a developer happened to remember to add an if-check.\n\n:::muted\nHow it works\n:::\nA DTO paired with a validation step at the entry point checks the whole shape of the incoming request up front and returns a clear error list immediately if anything is wrong; only a request that already passed gets handed to the service.\n\n:::muted\nCommon pitfall\n:::\nScattered if-checks inside the service drift out of sync, miss edge cases nobody thought to re-check at every call site, and let malformed data slip through any path a check was forgotten on.\n\n:::muted\nGo deeper\n:::\nwhat about extra fields the client wasn't supposed to send, like isAdmin?","clozes":[{"n":1,"term":"the boundary","distractors":["the service layer","the database layer"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/1-api-design-and-graphql/5$t$, '231d8cc57', $t$0-fullstack-mastery/1-api-design-and-graphql$t$, 5, true, $t$junior$t$, NULL, $j${"vi":{"question":"REST có nhiều endpoint; GraphQL chỉ expose đúng một /graphql nhưng vẫn list, đọc, tạo và update được. Điều gì khiến một endpoint đó vẫn hoạt động như một contract thật sự?","tags":["GraphQL","Schema Design"]},"en":{"question":"REST has many endpoints; GraphQL exposes a single /graphql yet can list, read, create and update. What makes that one endpoint work as a real contract?","tags":["GraphQL","Schema Design"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\n{{c1::Schema::Resolver,URL của endpoint}} mới là contract thật — nó khai báo sẵn mọi type, field và quy tắc nullability, và client chọn đúng những field nó cần từ hình dạng đã khai báo đó, chứ không phải từ một URL duy nhất.\n\n:::muted\nCơ chế\n:::\nResolver chỉ là lớp nối mỏng phía sau mỗi field của schema — các hàm nhỏ lấy hoặc ghi dữ liệu cho đúng field đó — còn bản thân schema mới là thứ client, hay một công cụ, đọc để biết cái gì khả dụng.\n\n:::muted\nBẫy thường gặp\n:::\nNghĩ rằng một endpoint duy nhất nghĩa là không có contract gì cả, vì không có URL riêng cho từng operation để đọc — schema CHÍNH LÀ contract, chỉ diễn đạt bằng type và field thay vì bằng route.\n\n:::muted\nĐào sâu tiếp\n:::\nnếu client tự chọn field, làm sao nó phân biệt được một field bị lỗi với những field còn lại?","clozes":[{"n":1,"term":"Schema","distractors":["Resolver","URL của endpoint"]}]},"en":{"answer":":::muted\nTL;DR\n:::\n{{c1::The schema::The resolver,The endpoint URL}} is the real contract — it declares every type, field, and nullability rule up front, and the client selects exactly the fields it needs from that declared shape, not from the single URL.\n\n:::muted\nHow it works\n:::\nResolvers are just the thin wiring behind each schema field — small functions that fetch or mutate data for that one field — while the schema itself is what a client, or a tool, reads to know what's possible at all.\n\n:::muted\nCommon pitfall\n:::\nAssuming one endpoint means no contract at all, because there's no per-operation URL to read — the schema IS the contract, just expressed as types and fields instead of as routes.\n\n:::muted\nGo deeper\n:::\nif the client picks fields, how does it tell one failed field apart from the rest?","clozes":[{"n":1,"term":"The schema","distractors":["The resolver","The endpoint URL"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/1-api-design-and-graphql/6$t$, '231d8cc57', $t$0-fullstack-mastery/1-api-design-and-graphql$t$, 6, true, $t$middle$t$, NULL, $j${"vi":{"question":"Một gateway retry lại request sau khi timeout. Method HTTP nào an toàn để retry mù, method nào thì không — và tính chất nào quyết định điều đó?","tags":["Idempotency","HTTP Semantics"]},"en":{"question":"A gateway retries a request after a timeout. Which HTTP methods are safe to retry blindly and which aren't — and what's the property that decides?","tags":["Idempotency","HTTP Semantics"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nTính chất quyết định là tính {{c1::idempotent::safe,cacheable}} — gọi lại bao nhiêu lần cũng đưa server về đúng một trạng thái như gọi một lần; GET, PUT và DELETE có tính chất đó, POST thì không.\n\n:::muted\nCơ chế\n:::\nGET chỉ đọc và không bao giờ đổi trạng thái, PUT thay thế resource bằng đúng representation đó mỗi lần, còn DELETE xoá một resource đã mất rồi thì vẫn cứ là mất — tất cả lặp lại được mà không thêm tác dụng phụ. POST thường tạo ra thứ mới mỗi lần, nên gọi hai lần có thể tạo ra hai bản.\n\n:::muted\nTrade-off\n:::\nIdempotent không đồng nghĩa với safe — GET vừa safe (không đổi trạng thái chút nào) vừa idempotent, nhưng DELETE idempotent trong khi rõ ràng đổi trạng thái ngay lần chạy đầu tiên; gateway có thể retry cả hai, nhưng chỉ GET mới cache hay prefetch được.\n\n:::muted\nBẫy thường gặp\n:::\nTự động retry mù một POST khi timeout có thể âm thầm tạo cùng một đơn hàng hay giao dịch tới hai lần, vì gateway không có cách nào biết request gốc đã thành công ở phía server trước khi timeout hay chưa.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy làm sao để một POST trở nên an toàn khi retry?","clozes":[{"n":1,"term":"idempotent","distractors":["safe","cacheable"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nThe property that decides is being {{c1::idempotent::safe,cacheable}} — repeating the call any number of times lands the server in the same state as calling it once; GET, PUT, and DELETE have that property, POST does not.\n\n:::muted\nHow it works\n:::\nGET reads and never changes state, PUT replaces a resource with the same representation every time, and DELETE removing an already-gone resource is still just gone — all repeatable with no extra effect. POST typically creates something new each time, so calling it twice can create it twice.\n\n:::muted\nTrade-off\n:::\nIdempotent is not the same as safe — GET is both safe (no state change at all) and idempotent, but DELETE is idempotent while clearly changing state the first time it runs; a gateway can retry both, but only GET can also be cached or prefetched.\n\n:::muted\nCommon pitfall\n:::\nBlindly auto-retrying a POST on timeout can silently create the same order or charge twice, because the gateway has no way to know whether the original request actually succeeded server-side before the timeout.\n\n:::muted\nGo deeper\n:::\nso how do you make a POST safe to retry anyway?","clozes":[{"n":1,"term":"idempotent","distractors":["safe","cacheable"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/1-api-design-and-graphql/7$t$, '231d8cc57', $t$0-fullstack-mastery/1-api-design-and-graphql$t$, 7, true, $t$middle$t$, NULL, $j${"vi":{"question":"Một endpoint signup copy thẳng request body lên entity. Một user gửi thêm field \"role\": \"admin\". Đây là lỗ hổng gì và làm sao chặn nó?","tags":["Validation","Security"]},"en":{"question":"A signup endpoint copies the request body straight onto the entity. A user sends an extra \"role\": \"admin\" field. What's the vulnerability and how do you shut it?","tags":["Validation","Security"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nĐây là {{c1::mass assignment::SQL injection,over-fetching}} — bất kỳ field nào client gửi kèm đều bị gán thẳng lên entity, nên một field role không nằm trong danh sách cho phép âm thầm nâng một lượt signup thành tài khoản admin; chặn bằng cách chỉ whitelist đúng những field DTO khai báo.\n\n:::muted\nCơ chế\n:::\nThay vì spread thẳng request body lên entity, handler dựng entity từ một whitelist tường minh gồm đúng những field DTO thật sự khai báo — bất kỳ thứ gì khác trong payload đơn giản là không bao giờ được đọc tới.\n\n:::muted\nBẫy thường gặp\n:::\nTin vào hình dạng payload vì nghĩ client \"không nên\" gửi field đó — mọi field đầu vào phải bị coi là thù địch cho tới khi được whitelist tường minh, vì không gì trên đường truyền ngăn client gửi nó cả.","clozes":[{"n":1,"term":"mass assignment","distractors":["SQL injection","over-fetching"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nThis is {{c1::mass assignment::SQL injection,over-fetching}} — any field the client includes gets bound straight onto the entity, so an unlisted role field silently escalates a signup into an admin account; shut it by whitelisting only the declared DTO fields.\n\n:::muted\nHow it works\n:::\nInstead of spreading the raw request body onto the entity, the handler builds the entity from an explicit whitelist of fields the DTO actually declares — anything else in the payload is simply never read.\n\n:::muted\nCommon pitfall\n:::\nTrusting the payload's shape because the client \"shouldn't\" send that field — every inbound field has to be treated as hostile until it's been explicitly whitelisted, because nothing on the wire stops a client from sending it anyway.","clozes":[{"n":1,"term":"mass assignment","distractors":["SQL injection","over-fetching"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/1-api-design-and-graphql/8$t$, '231d8cc57', $t$0-fullstack-mastery/1-api-design-and-graphql$t$, 8, true, $t$middle$t$, NULL, $j${"vi":{"question":"Một API chỗ này trả { data }, chỗ kia trả { error }, chỗ khác lại trả một chuỗi trần. Vì sao nên gom mọi response về một hình dạng nhất quán, và enforce ở đâu?","tags":["Error Handling","API Design"]},"en":{"question":"An API returns { data } here, { error } there, and a bare string elsewhere. Why centralize every response into one consistent shape, and where do you enforce it?","tags":["Error Handling","API Design"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nGom mọi response về một {{c1::envelope::status code,schema}} nhất quán, enforce tại đúng hai điểm chốt toàn cục — một interceptor cho thành công và một exception filter cho lỗi — để mọi client chỉ cần parse đúng một hình dạng bất kể handler nào trả lời.\n\n:::muted\nCơ chế\n:::\nMột interceptor thành công bọc giá trị trả về của mọi handler thành công vào cùng một envelope data, còn một exception filter toàn cục bắt mọi lỗi bị throw và format thành cùng một envelope error — không cái nào phụ thuộc vào việc từng handler riêng lẻ có nhớ làm đúng hay không.\n\n:::muted\nBẫy thường gặp\n:::\nĐể mỗi handler tự định hình response của mình khiến client phải rẽ nhánh theo từng endpoint chỉ để đọc kết quả, và việc truy vết một sự cố qua các hình dạng không nhất quán biến thành đoán mò thay vì tra cứu có thể dự đoán được.\n\n:::muted\nĐào sâu tiếp\n:::\nenvelope lỗi nhất định không được chứa gì khi xảy ra một lỗi 500 bất ngờ?","clozes":[{"n":1,"term":"envelope","distractors":["status code","schema"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nCentralize every response into one consistent {{c1::envelope::status code,schema}}, enforced at two global choke points — a success interceptor and an exception filter — so every client parses exactly one shape regardless of which handler answered.\n\n:::muted\nHow it works\n:::\nA success interceptor wraps every successful handler's return value into the same data envelope, and a global exception filter catches every thrown error and formats it into the same error envelope — neither depends on any individual handler remembering to do it right.\n\n:::muted\nCommon pitfall\n:::\nLetting each handler shape its own response means clients end up branching per endpoint just to read a result, and tracing an incident across inconsistent shapes turns into guesswork instead of a predictable lookup.\n\n:::muted\nGo deeper\n:::\nwhat must the error envelope deliberately NOT contain for an unexpected 500?","clozes":[{"n":1,"term":"envelope","distractors":["status code","schema"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/1-api-design-and-graphql/9$t$, '231d8cc57', $t$0-fullstack-mastery/1-api-design-and-graphql$t$, 9, true, $t$middle$t$, NULL, $j${"vi":{"question":"Một feed dùng offset/limit. Trong lúc user đang cuộn, item mới được chèn vào đầu danh sách. Chuyện gì hỏng, và vì sao lỗi này nằm sẵn trong chính cơ chế đó?","tags":["Pagination","API Design"]},"en":{"question":"A feed uses offset/limit. While a user scrolls, new items get inserted at the head. What goes wrong, and why is it inherent to this scheme?","tags":["Pagination","API Design"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\n{{c1::Offset::Cursor,Keyset}} đếm theo vị trí trong danh sách chứ không phải theo danh tính, nên ngay khi một item được chèn vào đầu, mọi vị trí phía sau dịch đi một bậc và trang tiếp theo đọc đúng một cửa sổ không còn khớp với những gì user đã thấy.\n\n:::muted\nCơ chế\n:::\nTrang 2 yêu cầu các dòng bắt đầu từ vị trí 20; nếu có 3 item mới chèn vào đầu kể từ khi trang 1 tải xong, vị trí 20 bây giờ trỏ sớm hơn 3 dòng so với lúc trước, nên server trả về những dòng client đã render rồi.\n\n:::muted\nBẫy thường gặp\n:::\nItem bị bỏ sót hoặc hiện trùng ngay giữa lúc cuộn, và đây không phải bug có thể vá bằng code ứng dụng — nó nằm sẵn trong việc đếm theo vị trí, vì con số đó chỉ chính xác đúng khoảnh khắc không có ai khác đang ghi vào danh sách.\n\n:::muted\nĐào sâu tiếp\n:::\nmô hình pagination nào vẫn ổn định khi danh sách bị thay đổi giữa chừng?","clozes":[{"n":1,"term":"Offset","distractors":["Cursor","Keyset"]}]},"en":{"answer":":::muted\nTL;DR\n:::\n{{c1::Offset::Cursor,Keyset}} counts positions in the list, not identities, so the moment an item is inserted at the head, every position downstream shifts by one and the next page reads a window that no longer lines up with what the user already saw.\n\n:::muted\nHow it works\n:::\nPage 2 asks for rows starting at position 20; if 3 new items landed at the head since page 1 loaded, position 20 now points 3 rows earlier than it did a moment ago, so the server returns rows the client already rendered.\n\n:::muted\nCommon pitfall\n:::\nItems get skipped or shown twice mid-scroll, and it's not a bug you can patch in application code — it's inherent to counting by position, because the count is only accurate the instant nothing else is writing to the list.\n\n:::muted\nGo deeper\n:::\nwhat pagination model stays stable when the list mutates?","clozes":[{"n":1,"term":"Offset","distractors":["Cursor","Keyset"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/1-api-design-and-graphql/10$t$, '231d8cc57', $t$0-fullstack-mastery/1-api-design-and-graphql$t$, 10, true, $t$middle$t$, NULL, $j${"vi":{"question":"Một query list 50 author, mỗi author có field books. Log cho thấy 51 lượt truy vấn database cho đúng một request. Pattern này gọi là gì và vì sao nó scale tệ đến vậy?","tags":["GraphQL","Performance"]},"en":{"question":"A query lists 50 authors, each with a books field. Your logs show 51 database hits for one request. What is this pattern called and why does it scale so badly?","tags":["GraphQL","Performance"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nĐây là pattern {{c1::N+1::fan-out,cartesian join}} — một query load 50 author, rồi field books của từng author độc lập bắn ra truy vấn database riêng của nó, tổng cộng 51 lượt truy vấn cho đúng một request GraphQL.\n\n:::muted\nCơ chế\n:::\nNested resolver theo mặc định chạy riêng cho từng phần tử — resolver books không hề biết nó đang bị gọi 50 lần cho 50 author anh em, nên nó cứ truy vấn database đúng một lần mỗi lượt gọi, y như thể nó là lượt gọi duy nhất.\n\n:::muted\nBẫy thường gặp\n:::\nĐộ trễ và tình trạng cạn kiệt connection pool tăng tuyến tính theo kích thước kết quả — một trang 50 author tốn 51 truy vấn, một trang 500 author tốn 501, và bản thân query chẳng bao giờ đổi hình dạng để cảnh báo trước.\n\n:::muted\nĐào sâu tiếp\n:::\ntầng nào gom N truy vấn con đó lại thành một?","clozes":[{"n":1,"term":"N+1","distractors":["fan-out","cartesian join"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nThis is the {{c1::N+1::fan-out,cartesian join}} pattern — one query loads the 50 authors, then each author's books field independently fires its own database query, for 51 total hits from a single GraphQL request.\n\n:::muted\nHow it works\n:::\nNested resolvers run per element by default — the books resolver has no idea it's being called 50 times for 50 sibling authors, so it just hits the database once per call, exactly as if it were the only one.\n\n:::muted\nCommon pitfall\n:::\nLatency and connection-pool exhaustion grow linearly with the result set size — a 50-author page costs 51 queries, a 500-author page costs 501, and the query itself never changed shape to warn you.\n\n:::muted\nGo deeper\n:::\nwhat layer collapses those N child queries into one?","clozes":[{"n":1,"term":"N+1","distractors":["fan-out","cartesian join"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/1-api-design-and-graphql/11$t$, '231d8cc57', $t$0-fullstack-mastery/1-api-design-and-graphql$t$, 11, true, $t$middle$t$, NULL, $j${"vi":{"question":"Resolver của một field non-null throw lỗi hoặc trả về null lúc runtime. GraphQL xử lý response xung quanh nó thế nào, và vì sao đánh dấu một field là non-null lại là một quyết định thiết kế thật sự?","tags":["GraphQL","Schema Design"]},"en":{"question":"A resolver for a non-null field throws or returns null at runtime. What does GraphQL do to the surrounding response, and why is marking a field non-null a real design decision?","tags":["GraphQL","Schema Design"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nNull sẽ {{c1::lan lên::bị nuốt mất,trả null tại chỗ}} tới tổ tiên gần nhất được phép null — một field non-null thất bại không chỉ tự nó thành null, nó khiến cả object cha bị vô hiệu, và tiếp tục lan lên cho tới khi gặp một field được phép null.\n\n:::muted\nCơ chế\n:::\nNon-null là một cam kết chặt engine thực thi enforce ở tầng type: nếu một field đánh dấu non-null không thể tạo ra giá trị, engine coi cả object cha là không hợp lệ thay vì âm thầm trả về null đúng ngay chỗ đó.\n\n:::muted\nBẫy thường gặp\n:::\nĐánh dấu mọi field là non-null \"cho chắc\" nghĩa là một field không ổn định ở bất kỳ đâu trong cây cũng có thể xoá trắng cả một nhánh anh em chẳng liên quan gì tới lỗi — nullability thực chất là một quyết định về bán kính ảnh hưởng, không chỉ là chuyện chặt chẽ về type.","clozes":[{"n":1,"term":"lan lên","distractors":["bị nuốt mất","trả null tại chỗ"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nNull {{c1::propagates::is swallowed,returns null in place}} up to the nearest nullable ancestor — a non-null field that fails doesn't just go null itself, it nullifies its entire parent object, and keeps bubbling up until it finds a field allowed to be null.\n\n:::muted\nHow it works\n:::\nNon-null is a strict guarantee the execution engine enforces at the type level: if a field marked non-null cannot produce a value, the engine treats the whole parent as invalid rather than silently handing back a null in that one spot.\n\n:::muted\nCommon pitfall\n:::\nMarking every field non-null \"to be safe\" means one flaky field anywhere in the tree can blank out an entire sibling subtree that had nothing to do with the failure — nullability is really a blast-radius decision, not just a type-strictness one.","clozes":[{"n":1,"term":"propagates","distractors":["is swallowed","returns null in place"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/1-api-design-and-graphql/12$t$, '231d8cc57', $t$0-fullstack-mastery/1-api-design-and-graphql$t$, 12, true, $t$senior$t$, NULL, $j${"vi":{"question":"Một POST thanh toán timeout và client retry lại; bạn không muốn tính tiền hai lần. Làm sao khiến một POST không idempotent trở nên an toàn khi retry?","tags":["Idempotency","Reliability"]},"en":{"question":"A payments POST times out and the client retries; you don't want to charge twice. How do you make a non-idempotent POST safe to retry?","tags":["Idempotency","Reliability"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nClient đính kèm một {{c1::idempotency key::nonce,correlation id}} — một giá trị duy nhất cho mỗi lượt thao tác logic — và server ghi lại kết quả dưới key đó, phát lại đúng kết quả đã lưu thay vì thực thi lại giao dịch khi nhận request lặp lại với cùng key.\n\n:::muted\nCơ chế\n:::\nViệc khử trùng lặp diễn ra tại key, không phải tại payload: server kiểm tra xem đã xử lý đúng key này chưa trước khi làm bất cứ việc gì, và nếu rồi, trả lại đúng response đã lưu trước đó thay vì tính tiền lần nữa.\n\n:::muted\nTrade-off\n:::\nLấy key từ hash của request body thay vì để client tự sinh và sở hữu key sẽ phá vỡ trường hợp client thật sự muốn tính đúng số tiền đó hai lần — bạn còn phải chọn một cửa sổ lưu trữ cho các key, đánh đổi chi phí lưu trữ với khoảng thời gian một retry còn được phép \"hạ cánh\" an toàn.\n\n:::muted\nBẫy thường gặp\n:::\nSuy ra key từ payload thay vì để client tự sinh và sở hữu nó gộp lẫn \"cùng nội dung\" với \"cùng một lượt thao tác logic\" — hai giao dịch hợp lệ, độc lập với cùng số tiền bị khử trùng lặp nhầm thành một.\n\n:::muted\nĐào sâu tiếp\n:::\nnếu hai request mang cùng idempotency key tới cùng một thời điểm, trước khi request nào xử lý xong, thì nên xử lý thế nào?","clozes":[{"n":1,"term":"idempotency key","distractors":["nonce","correlation id"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nThe client attaches an {{c1::idempotency key::nonce,correlation id}} — one unique value per logical operation — and the server records the outcome under that key, replaying the stored result instead of re-executing the charge on a repeated request with the same key.\n\n:::muted\nHow it works\n:::\nDedupe happens at the key, not at the payload: the server checks whether it has already processed this exact key before doing any work, and if so, returns the previously stored response verbatim rather than charging again.\n\n:::muted\nTrade-off\n:::\nKeying on a hash of the request body instead of an explicit client-supplied key breaks the case where a client genuinely wants to charge the same amount twice — you also have to pick a retention window for stored keys, trading storage cost against how long a retry can safely land.\n\n:::muted\nCommon pitfall\n:::\nDeriving the key from the payload rather than letting the client generate and own it conflates \"same content\" with \"same logical attempt\" — two legitimate separate charges for the same amount get incorrectly deduped into one.\n\n:::muted\nGo deeper\n:::\nwhat should happen if two requests carrying the same idempotency key arrive at the same instant, before either has finished?","clozes":[{"n":1,"term":"idempotency key","distractors":["nonce","correlation id"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/1-api-design-and-graphql/13$t$, '231d8cc57', $t$0-fullstack-mastery/1-api-design-and-graphql$t$, 13, true, $t$senior$t$, NULL, $j${"vi":{"question":"Bạn đang triage các lỗi. Làm sao quyết định một lỗi là do phía client hay do phía bạn, và quyết định đó dẫn dắt việc retry và alerting ra sao?","tags":["Error Handling","Reliability"]},"en":{"question":"You're triaging failures. How do you decide whether a failure is the client's fault or yours, and how does that decision drive retry and alerting?","tags":["Error Handling","Reliability"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\n{{c1::4xx::5xx,3xx}} nghĩa là client phải đổi request trước khi có thể thành công — đừng tự động retry và đừng page on-call — còn 5xx nghĩa là lỗi nằm ở phía server, retry được và đáng để cảnh báo.\n\n:::muted\nCơ chế\n:::\nViệc quy trách nhiệm lỗi chính là contract dẫn dắt hành vi tự động: một chính sách retry chỉ retry 5xx và vài mã mơ hồ cụ thể, một rule alerting chỉ page on-call cho 5xx, vì một loạt 4xx thường chỉ có nghĩa client đang gửi request sai, không phải server đang có vấn đề.\n\n:::muted\nTrade-off\n:::\nMột số mã thật sự mơ hồ — 429 và 409 nằm trong vùng xám, retry có giúp ích hay không tuỳ tình huống, nên hệ thống phải gắn kèm chỉ dẫn retry tường minh, như header Retry-After, thay vì chỉ dựa vào nhóm status.\n\n:::muted\nBẫy thường gặp\n:::\nTrả 500 cho một lỗi validation làm ngập alert on-call vì một thứ chưa bao giờ là vấn đề của server, và còn có thể kích hoạt retry tự động sẽ không bao giờ thành công dù chạy lại bao nhiêu lần.\n\n:::muted\nĐào sâu tiếp\n:::\nvới các mã thật sự mơ hồ như 429, bạn gắn thêm tín hiệu gì để client đang retry biết có nên thử lại hay không và khi nào?","clozes":[{"n":1,"term":"4xx","distractors":["5xx","3xx"]}]},"en":{"answer":":::muted\nTL;DR\n:::\n{{c1::4xx::5xx,3xx}} means the client has to change the request before it can succeed — don't retry it automatically and don't page on-call — while 5xx means the fault is server-side, which is retriable and worth alerting on.\n\n:::muted\nHow it works\n:::\nFault attribution is itself the contract that drives automated behavior: a retry policy only retries 5xx and specific ambiguous codes, and an alerting rule only pages on-call for 5xx, because a flood of 4xx usually just means clients are sending bad requests, not that the server is unhealthy.\n\n:::muted\nTrade-off\n:::\nSome codes are genuinely ambiguous — 429 and 409 sit in a gray zone where a retry might or might not help depending on the situation, so systems have to give explicit retry guidance, like a Retry-After header, rather than relying on the status class alone.\n\n:::muted\nCommon pitfall\n:::\nReturning 500 for a validation failure floods on-call with alerts for something that was never a server problem, and can also trigger automated retries that will never succeed no matter how many times they run.\n\n:::muted\nGo deeper\n:::\nfor the genuinely ambiguous codes like 429, what extra signal do you attach so a retrying client knows whether and when to try again?","clozes":[{"n":1,"term":"4xx","distractors":["5xx","3xx"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/1-api-design-and-graphql/14$t$, '231d8cc57', $t$0-fullstack-mastery/1-api-design-and-graphql$t$, 14, true, $t$senior$t$, NULL, $j${"vi":{"question":"Một lỗi 500 bất ngờ thường mang message thật chứa stack trace hoặc một chuỗi SQL thô. Vì sao tuyệt đối không được chuyển tiếp message đó nguyên văn cho client, dù nó trông có vẻ hữu ích?","tags":["Error Handling","Security"]},"en":{"question":"An unexpected 500's real message often carries a stack trace or a raw SQL string. Why must you never forward that literal message to the client, even though it looks helpful?","tags":["Error Handling","Security"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nThay vào đó chuyển tiếp một message {{c1::chung chung::rỗng,đã dịch}} đã được che đi — message nội bộ thật tiết lộ chi tiết triển khai cho bất kỳ ai kích hoạt được lỗi đó, và nó cũng chẳng hữu ích gì với client, vì client không làm gì được với một stack trace cả.\n\n:::muted\nCơ chế\n:::\nLỗi đã lường trước được gán một message an toàn, viết tay có chủ đích dành cho client; lỗi bất ngờ được gán một message chung chung cố định, còn chi tiết thật — stack trace, câu query, trạng thái nội bộ — chỉ được đưa vào log phía server, không bao giờ vào response body.\n\n:::muted\nTrade-off\n:::\nBạn vẫn nên giữ lại request id, path và timestamp trên response đã che, để support truy vết sự cố trong log mà không lộ chi tiết thật — cắt trụi mọi thứ chỉ còn một nhãn lỗi trơ trọi khiến ngay cả việc triage hợp lệ của support cũng khó hơn.\n\n:::muted\nBẫy thường gặp\n:::\nNgay cả một message trông có vẻ hữu ích vô hại cho validation cũng có thể để lộ tên cột thật, tên service nội bộ, hoặc email thật của một user cho kẻ đang dò API — mọi chuỗi hiển thị cho client phải bị coi là công khai trước khi được xem là an toàn.\n\n:::muted\nĐào sâu tiếp\n:::\nđiều gì xảy ra nếu chính message lỗi validation được dựng bằng cách nội suy thẳng input của user trở lại vào response?","clozes":[{"n":1,"term":"chung chung","distractors":["rỗng","đã dịch"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nForward a {{c1::generic::empty,translated}} masked message instead — the real internal message discloses implementation details to anyone who can trigger the failure, and it's not even useful to the client, who can't act on a stack trace anyway.\n\n:::muted\nHow it works\n:::\nExpected errors get a deliberate, safe, hand-written message meant for the client; unexpected errors get a fixed generic message while the actual detail — stack trace, query, internal state — is routed only to server-side logs, never to the response body.\n\n:::muted\nTrade-off\n:::\nYou still want to carry a request id, a path, and a timestamp on the masked response so support can trace the incident in logs without exposing the detail itself — stripping everything down to a bare error label with nothing else makes even legitimate support triage harder.\n\n:::muted\nCommon pitfall\n:::\nEven a message that looks harmlessly helpful for validation can leak a real column name, an internal service name, or a user's actual email back to an attacker probing the API — every client-facing string has to be treated as public before it's decided to be safe.\n\n:::muted\nGo deeper\n:::\nwhat happens if a validation error message itself is built by interpolating raw user input back into the response?","clozes":[{"n":1,"term":"generic","distractors":["empty","translated"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/1-api-design-and-graphql/15$t$, '231d8cc57', $t$0-fullstack-mastery/1-api-design-and-graphql$t$, 15, true, $t$senior$t$, NULL, $j${"vi":{"question":"Bạn đã xác định được N+1 trên một field lồng nhau. DataLoader thực sự loại bỏ nó bằng cách nào, và hai cơ chế riêng biệt của nó là gì?","tags":["GraphQL","DataLoader"]},"en":{"question":"You've identified N+1 on a nested field. How does DataLoader actually eliminate it, and what are its two distinct mechanisms?","tags":["GraphQL","DataLoader"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nDataLoader {{c1::gộp lô::chạy song song,khử trùng lặp}} mọi lệnh load phát ra trong cùng một tick của event loop thành một truy vấn duy nhất, và tách riêng ra việc cache kết quả theo từng request để một key đã load rồi không bao giờ bị hỏi lại lần hai.\n\n:::muted\nCơ chế\n:::\nThay vì mỗi resolver truy vấn database ngay lúc được gọi, các lệnh load một key được gom lại trong tick hiện tại; khi tick kết thúc, DataLoader gọi đúng một hàm batch với toàn bộ key đã gom, rồi phân phối kết quả ngược lại cho từng nơi gọi ban đầu.\n\n:::muted\nTrade-off\n:::\nHàm batch phải trả về kết quả đúng theo thứ tự các key được đưa vào, nếu không việc ánh xạ ngược lại từng nơi gọi sẽ âm thầm lệch nhau — một yêu cầu đúng đắn tinh vi đánh đổi lấy việc gộp N truy vấn thành một.\n\n:::muted\nBẫy thường gặp\n:::\nMột instance DataLoader sống lâu hơn một request duy nhất sẽ làm rò rỉ cache theo-request của nó sang giữa các user — kết quả cache của một user cho một key có thể bị âm thầm phục vụ cho request của một user hoàn toàn khác.\n\n:::muted\nĐào sâu tiếp\n:::\nvì sao điều đó nghĩa là DataLoader phải được khởi tạo mới cho từng request đến, thay vì khởi tạo một lần lúc app khởi động?","clozes":[{"n":1,"term":"gộp lô","distractors":["chạy song song","khử trùng lặp"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nDataLoader {{c1::batches::parallelizes,deduplicates}} every load call issued within a single event-loop tick into one query, and separately caches results per request so an already-loaded key is never asked for twice.\n\n:::muted\nHow it works\n:::\nInstead of each resolver hitting the database the instant it's called, calls to load a key are collected across the current tick; once the tick ends, DataLoader fires one batch function call with every collected key and fans the results back out to each original caller.\n\n:::muted\nTrade-off\n:::\nThe batch function must return results in exactly the same order as the keys it was given, or the mapping back to each caller silently misaligns — a subtle correctness requirement traded for the collapse from N queries to one.\n\n:::muted\nCommon pitfall\n:::\nA DataLoader instance that lives longer than a single request leaks its per-request cache across users — one user's cached result for a key can be silently served to a completely different user's request.\n\n:::muted\nGo deeper\n:::\nwhy does that mean a DataLoader has to be instantiated fresh per incoming request rather than once at app startup?","clozes":[{"n":1,"term":"batches","distractors":["parallelizes","deduplicates"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/1-api-design-and-graphql/16$t$, '231d8cc57', $t$0-fullstack-mastery/1-api-design-and-graphql$t$, 16, true, $t$senior$t$, NULL, $j${"vi":{"question":"GraphQL cho client tự chọn field, nên một kẻ tấn công có thể gửi một query lồng sâu resolve tới hàng nghìn field. Làm sao phòng thủ endpoint mà không phá các query hợp lệ?","tags":["GraphQL","Query Cost"]},"en":{"question":"GraphQL lets a client pick fields, so an attacker can send a deeply nested query that resolves thousands of fields. How do you defend the endpoint without breaking legit queries?","tags":["GraphQL","Query Cost"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nGán chi phí cho từng field, cộng tổng chi phí của query được yêu cầu, và từ chối bất kỳ query nào vượt ngưỡng {{c1::trước khi thực thi::sau khi thực thi,ở từng resolver lúc runtime}} — một plugin ở giai đoạn resolve-operation chặn query trước khi bất kỳ resolver nào chạy.\n\n:::muted\nCơ chế\n:::\nTrọng số tĩnh cho từng field, hoặc tính động cho các field nhân lên theo list, được cộng dồn trên toàn bộ selection được yêu cầu tại lúc parse và validate; nếu tổng vượt ngưỡng cấu hình, operation bị từ chối thẳng trước khi chạm tới database.\n\n:::muted\nTrade-off\n:::\nTrọng số tĩnh theo field rẻ để tính nhưng chỉ ước lượng gần đúng chi phí thật; một chi phí đo runtime chính xác hơn bắt được nhiều lạm dụng hơn nhưng không thể từ chối query trước khi nó đã làm xong phần việc tốn kém — bạn đang đánh đổi độ chính xác lấy khả năng chặn sớm.\n\n:::muted\nBẫy thường gặp\n:::\nChỉ đo chi phí sau khi đã thực thi xong thì phá hỏng toàn bộ mục đích — phần việc database tốn kém đã xảy ra rồi vào lúc bạn quyết định lẽ ra query đó phải bị từ chối.\n\n:::muted\nĐào sâu tiếp\n:::\nngoài việc chặn query tốn kém, làm sao khoá client chỉ được gửi những query đã được duyệt trước?","clozes":[{"n":1,"term":"trước khi thực thi","distractors":["sau khi thực thi","ở từng resolver lúc runtime"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nAssign every field a cost, sum the requested query's total cost, and reject anything over a threshold {{c1::before execution::after execution,per resolver at runtime}} — a plugin at the resolve-operation stage blocks the query before a single resolver runs.\n\n:::muted\nHow it works\n:::\nStatic per-field weights, or dynamically computed ones for list-multiplying fields, get summed across the whole requested selection at parse and validation time; if the total exceeds the configured ceiling, the operation is rejected outright before touching the database.\n\n:::muted\nTrade-off\n:::\nStatic per-field weights are cheap to compute but only approximate real cost; a more accurate runtime-measured cost catches more abuse but can't reject the query before it has already done the expensive work — you're trading precision for the ability to block early.\n\n:::muted\nCommon pitfall\n:::\nMeasuring cost only after execution defeats the entire purpose — the expensive database work already happened by the time you decide the query should have been rejected.\n\n:::muted\nGo deeper\n:::\nbeyond blocking expensive queries, how do you lock clients down to only pre-approved ones?","clozes":[{"n":1,"term":"before execution","distractors":["after execution","per resolver at runtime"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/1-api-design-and-graphql/17$t$, '231d8cc57', $t$0-fullstack-mastery/1-api-design-and-graphql$t$, 17, true, $t$senior$t$, NULL, $j${"vi":{"question":"Trong một response GraphQL, một số field resolve tốt còn một field thất bại. Khác với REST, response trông như thế nào, và client nên rẽ nhánh theo lỗi ra sao?","tags":["GraphQL","Error Handling"]},"en":{"question":"In one GraphQL response some fields resolved fine and one failed. Unlike REST, what does the response look like, and how should a client branch on the failure?","tags":["GraphQL","Error Handling"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nGraphQL thường trả về HTTP 200 với một response {{c1::một phần::tất cả hoặc không gì,atomic}} — một object data chứa mọi field resolve tốt, đi kèm một mảng errors mô tả đúng field nào thất bại và vì sao.\n\n:::muted\nCơ chế\n:::\nClient đọc code ổn định trong extensions của từng phần tử errors để rẽ nhánh theo lỗi bằng lập trình, chứ không bao giờ dựa vào chuỗi message dành cho người đọc, vì message có thể đổi cách diễn đạt bất cứ lúc nào trong khi code vẫn là một contract cố định.\n\n:::muted\nTrade-off\n:::\nThành công một phần rất mạnh — một trang vẫn render được những field đã thành công thay vì hỏng cả màn hình — nhưng nó buộc mọi client phải chủ động xử lý một response trả lời nửa chừng thay vì coi một request chỉ đơn giản là thành công hoặc thất bại.\n\n:::muted\nBẫy thường gặp\n:::\nCoi việc mảng errors không rỗng là thất bại toàn bộ sẽ vứt bỏ mọi field thực sự đã resolve thành công, và rẽ nhánh theo chuỗi message thay vì theo code sẽ hỏng ngay khi cách diễn đạt đổi.\n\n:::muted\nĐào sâu tiếp\n:::\nnếu client chỉ muốn retry đúng field đã thất bại mà không fetch lại toàn bộ, việc đó đòi hỏi gì từ cách thiết kế query?","clozes":[{"n":1,"term":"một phần","distractors":["tất cả hoặc không gì","atomic"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nGraphQL typically returns HTTP 200 with a {{c1::partial::all-or-nothing,atomic}} response — a data object holding every field that resolved fine, alongside an errors array describing exactly which field failed and why.\n\n:::muted\nHow it works\n:::\nThe client reads a stable errors extensions code to branch on the failure programmatically, never the human-readable message string, since the message can change wording without notice while the code stays a fixed contract.\n\n:::muted\nTrade-off\n:::\nPartial success is powerful — a page can still render the fields that succeeded instead of failing the whole screen — but it forces every client to deliberately handle a half-answered response instead of treating a request as simply success or failure.\n\n:::muted\nCommon pitfall\n:::\nTreating the mere presence of a non-empty errors array as total failure throws away every field that actually resolved successfully, and branching on the message string instead of the code breaks the moment wording changes.\n\n:::muted\nGo deeper\n:::\nif the client needs to retry only the field that failed without refetching everything, what does that require from the query's design?","clozes":[{"n":1,"term":"partial","distractors":["all-or-nothing","atomic"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/1-api-design-and-graphql/18$t$, '231d8cc57', $t$0-fullstack-mastery/1-api-design-and-graphql$t$, 18, true, $t$senior$t$, NULL, $j${"vi":{"question":"Bạn cần pagination không bỏ sót hay trùng lặp dòng khi danh sách bị thay đổi giữa lúc cuộn. Một connection kiểu Relay dùng cursor đạt được sự ổn định đó bằng cách nào mà offset thì không?","tags":["Pagination","GraphQL"]},"en":{"question":"You need pagination that doesn't skip or duplicate rows when the list mutates mid-scroll. How does a Relay-style cursor connection achieve stability where offset can't?","tags":["Pagination","GraphQL"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nMột {{c1::cursor::offset,số trang}} là mờ và trỏ vào đúng một vị trí trong thứ tự sắp xếp, chứ không phải một chỉ số — nên trang tiếp theo tiếp tục đọc từ đúng dòng đã biết đó bất kể bao nhiêu item bị chèn hay xoá ở chỗ khác trong danh sách.\n\n:::muted\nCơ chế\n:::\nMỗi item trong kết quả mang cursor riêng của nó, và thông tin trang mang một cursor cuối cùng cùng một cờ báo còn trang tiếp theo hay không; query của trang tiếp theo nói \"cho tôi các item sau đúng cursor này\" thay vì \"cho tôi các item bắt đầu từ vị trí số này.\"\n\n:::muted\nTrade-off\n:::\nCursor mang lại phân trang tiến ổn định khi dữ liệu bị thay đổi, nhưng khiến việc \"nhảy thẳng tới trang 7\" khó hoặc bất khả thi, vì cursor chỉ mã hoá đúng dòng ngay sau dòng này, không phải một vị trí tuyệt đối tuỳ ý.\n\n:::muted\nBẫy thường gặp\n:::\nĐể lộ một cursor chỉ là một chỉ số có thể giải mã, đoán được, như offset thô mã hoá bằng base64, mời gọi client tự bịa ra vị trí, phá hỏng toàn bộ mục đích coi cursor là mờ.\n\n:::muted\nĐào sâu tiếp\n:::\nlàm sao phân trang lùi, từ cuối danh sách, vẫn dùng đúng mô hình cursor này?","clozes":[{"n":1,"term":"cursor","distractors":["offset","số trang"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nA {{c1::cursor::offset,page number}} is opaque and points at a position in the ordering itself, not at an index — so the next page resumes reading from that exact known row regardless of how many items got inserted or removed elsewhere in the list.\n\n:::muted\nHow it works\n:::\nEach item in the results carries its own cursor, and the page info carries an end cursor plus a has-next-page flag; the next page's query says \"give me items after this exact cursor\" instead of \"give me items starting at this numeric position.\"\n\n:::muted\nTrade-off\n:::\nCursors buy stable forward paging under mutation, but they make \"jump straight to page 7\" hard or impossible, because a cursor only encodes the row right after this one, not an arbitrary absolute position.\n\n:::muted\nCommon pitfall\n:::\nExposing a cursor that's just a decodable, predictable index, like the raw offset encoded in base64, invites clients to fabricate positions themselves, defeating the whole point of treating the cursor as opaque.\n\n:::muted\nGo deeper\n:::\nhow would you paginate backward, from the end of the list, using the same cursor model?","clozes":[{"n":1,"term":"cursor","distractors":["offset","page number"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:0-fullstack-mastery/1-api-design-and-graphql/19$t$, '231d8cc57', $t$0-fullstack-mastery/1-api-design-and-graphql$t$, 19, true, $t$staff$t$, NULL, $j${"vi":{"question":"Một API GraphQL/REST duy nhất phục vụ một web app ngốn dữ liệu, một mobile app hạn chế băng thông, và các đối tác thứ ba. Làm sao kiến trúc API để mỗi client không bị ép vào hình dạng của client khác — và làm sao đồng thời ngăn client gửi query tuỳ ý?","tags":["API Design","Architecture"]},"en":{"question":"One GraphQL/REST API serves a data-hungry web app, a bandwidth-constrained mobile app, and third-party partners. How do you architect the API so each client isn't forced into another's shape — and how do you also stop clients sending arbitrary queries?","tags":["API Design","Architecture"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nCho mỗi nhóm client một bề mặt riêng được may đo — một {{c1::backend-for-frontend::API gateway,reverse proxy}} — thay vì một API chung khiến mobile over-fetch còn web bị thiếu dữ liệu, và tách riêng việc khoá query tuỳ ý bằng một allowlist persisted-query.\n\n:::muted\nCơ chế\n:::\nMỗi backend-for-frontend nằm giữa đúng một loại client và API lõi dùng chung, định hình và cắt gọt dữ liệu vừa đúng thứ client đó cần; độc lập với đó, một allowlist persisted-query đăng ký trước mọi query đã duyệt theo hash của nó, để client lúc runtime chỉ gửi hash, và server thực thi đúng query đã đăng ký khớp, chứ không bao giờ thực thi một query client tự gửi tuỳ ý.\n\n:::muted\nTrade-off\n:::\nBackend-for-frontend theo từng client cộng với pipeline persisted-query tạo ra sự ràng buộc thật sự giữa chu kỳ release của client và server — một query mới ở phía client phải được đăng ký ở phía server trước khi có thể ra mắt — đánh đổi sự linh hoạt khi deploy để lấy cả hiệu quả băng thông lẫn một bề mặt query đóng, giới hạn được chi phí.\n\n:::muted\nBẫy thường gặp\n:::\nMột API dùng chung duy nhất ép mọi client vào cùng một hình dạng thấp nhất chung, over-fetch cho mobile và thiếu dữ liệu cho web, và để ngỏ hoàn toàn bề mặt query cho bất kỳ hình dạng nào kẻ tấn công có thể dựng ra, vì không gì định hình hay giới hạn những gì được hỏi.\n\n:::muted\nĐào sâu tiếp\n:::\nlàm sao xử lý một query thật sự ad hoc, như một dashboard quản trị nội bộ, mà không phải bỏ qua allowlist lẫn không phải duy trì hẳn hai kiến trúc API tách biệt?","clozes":[{"n":1,"term":"backend-for-frontend","distractors":["API gateway","reverse proxy"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nGive each client class its own tailored surface — a {{c1::backend-for-frontend::API gateway,reverse proxy}} — instead of one shared API that over-fetches for mobile and under-serves web, and separately lock down arbitrary queries with a persisted-query allowlist.\n\n:::muted\nHow it works\n:::\nEach backend-for-frontend sits between its one client type and the shared core API, shaping and trimming data to exactly what that client needs; independently, a persisted-query allowlist registers every approved query by its hash ahead of time, so a client sends only the hash at runtime and the server executes the matching registered query, never an arbitrary client-supplied one.\n\n:::muted\nTrade-off\n:::\nPer-client backends-for-frontend plus a persisted-query pipeline add real coupling between client and server release cycles — a new client-side query has to be registered server-side before it can ship — trading deploy flexibility for both bandwidth efficiency and a closed, cost-bounded query surface.\n\n:::muted\nCommon pitfall\n:::\nA single shared API forces every client onto the same lowest-common-denominator shape, over-fetching for mobile and under-serving web, and leaves the query surface wide open to any shape an attacker can construct, since nothing shapes or restricts what gets asked.\n\n:::muted\nGo deeper\n:::\nhow do you handle a query that's genuinely ad hoc, like an internal admin dashboard, without either bypassing the allowlist or maintaining two entirely separate API architectures?","clozes":[{"n":1,"term":"backend-for-frontend","distractors":["API gateway","reverse proxy"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_decks (deck_id, course, sort_index, live_version, difficulty, titles, descriptions, module_refs, tracks, card_count, free_card_count, updated_at) VALUES ($t$0-fullstack-mastery/1-api-design-and-graphql$t$, $t$0-fullstack-mastery$t$, 1, '231d8cc57', $t$hard$t$, $j${"vi":"Thiết kế API: REST & GraphQL Contract","en":"API Design: REST & GraphQL Contracts"}$j$::jsonb, $j${"vi":"Câu hỏi phỏng vấn về những contract mà một API HTTP/GraphQL phơi ra: semantics của method và status code, idempotency và retry an toàn, validation ở biên, một hình dạng lỗi thống nhất, pagination offset so với cursor, cùng mô hình schema/nullability của GraphQL, N+1 và DataLoader, response partial-error, phòng thủ chi phí query, và kiến trúc API theo từng client.","en":"Interview questions on the contracts an HTTP/GraphQL API exposes: method and status-code semantics, idempotency and safe retries, boundary validation, a unified error shape, offset vs cursor pagination, plus GraphQL's schema/nullability model, N+1 and DataLoader, partial-error responses, query-cost defense, and per-client API architecture."}$j$::jsonb, $j$["rest-api-design-and-documentation","graphql-api-design"]$j$::jsonb, $j$["backend-fullstack","ai-engineer","founder"]$j$::jsonb, 20, 3, now()) ON CONFLICT (deck_id) DO NOTHING;
INSERT INTO review_deck_versions (deck_id, version, content_hash, source_hashes, imported_at) VALUES ($t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, '231d8cc57', $t$3ac9960740a3aedbd8b6e0dcfa90ebdc847a93eef2acebdc5a990955ec7ae076$t$, $j${"cards/0-card/en.md":"9613f9e5194f7042a5906fb4cdab72b5c625e95e033cde059bb2a1c345b3ec77","cards/0-card/vi.md":"09ea0a595be7ca32292d59fdf470ce9a67c72ac5789d480633fdd7df4835ff38","cards/1-card/en.md":"428adb8a8f219b8628c40f0df981337059a2c8fea4494a7c1e330296001a41d5","cards/1-card/vi.md":"f3e18dbdfce8f31ded558129a42f73104f1fad038604ea84a12d7c134f90b122","cards/10-card/en.md":"a2f50374e8bcaf1bf71658e9b823c1b5f26c1b7e029a745116b34d6e214e848e","cards/10-card/vi.md":"8a354321892be50b32867ada1103418ba401722a23170f266773cd7e67fcff5a","cards/11-card/en.md":"3592508b7f5a6c944a4a2c31b5f676e18050d0dd7e8f6a59a62d9e0bd0decd57","cards/11-card/vi.md":"ecf2c5668bccf9c3856537402c4e9eaa9b5e9dea617c5f59bdae3afe5109b037","cards/12-card/en.md":"26c09b3f4fa332a384dce576f8a79f2b0e9eca339148424997c95b3284a0dd9e","cards/12-card/vi.md":"42699220e66fe343c0f6bdc198d1548e10011eb6d9b978d6e581224e2bd103a4","cards/13-card/en.md":"0981910b774ce9b96bdfb015b410d2762c8324014ac70cf80a7f8754721c8e27","cards/13-card/vi.md":"1051710aabea7c8a0e80e243ae666751b9a477fe0d52c11009da6d2f6795d4eb","cards/14-card/en.md":"9ab4cdaad1bb73ba639cf286a965de9858d4f14b8cf77178275c956fae167867","cards/14-card/vi.md":"83213ec538ee0162b6dbf40e1e99a3e6c35423ba59eebb573c401ff62aa70eb8","cards/15-card/en.md":"b3ec1897183e0df2de51fb56370aba3605f6dc3ca5ec32756f7af7695c53499a","cards/15-card/vi.md":"6b00880bf2251b4f015653f81ccd6227670701af19c141c6ed93cb6bd4ee4ee9","cards/16-card/en.md":"643dc77a9742c938fc93395016f4126fcdc06f8335b124e6de74d987000b1a4c","cards/16-card/vi.md":"a7ab01abdbd757cae207279e01e9ea61f1b35e2b9e16998449fe13ee1fe5eb4d","cards/17-card/en.md":"72006532b3e449a6e3d57acfc53a59d46bf3bd3c782a35daf7fbde9b39d7f892","cards/17-card/vi.md":"5a5e5c210103afc47f5a470e472c2d5ff6735aa87dcbd3703fa709a569a84c81","cards/18-card/en.md":"ca3321c4c8bc940de24244fe6eeb4d76790b87c991d7119dc50ac63295bbcc9f","cards/18-card/vi.md":"0017cd7a1727b4e086082a88eaa6b59faeef7214fc7d4ac2f0925a7add7b1261","cards/19-card/en.md":"b32cd593aa5dcd5cad722de202361409761f3272791f7a503fef8706e1ebcf9d","cards/19-card/vi.md":"86a074d031f78a4601962eac34e5404234540c7ebc61fcc54446035fb5b837e2","cards/2-card/en.md":"5860e02be2169c42978948a9428bd1541eeb2f2ee24446da663d66572ca69ab0","cards/2-card/vi.md":"eb1b64e647e1ef49e7bbc00b98fee2353da8d81c0a986576a5d4a35bb7911135","cards/3-card/en.md":"d12e4e2c4c69b487512ac4057b9d8840d624dc021913e0e3f768e6e72d220c38","cards/3-card/vi.md":"ffb62b6fd975ed727dbad0dcd66a2cef20cc7b8b866adb99d8774d5ad28a3457","cards/4-card/en.md":"778b6e640542bed7673056d87a78b7269986a06f077411d1f80d9ebae207c28d","cards/4-card/vi.md":"80641d7e3c2646ce9c0de41184b4582c1508696627063e7ed615efb88271e245","cards/5-card/en.md":"88c6924c0d48ad8863b13963eadeaaffc9c63142dd4b652e46d4575231b913c8","cards/5-card/vi.md":"95e77e140815665da0a4dfc0e9c86b65ce47b18ff7c0b0775934038c39e5970d","cards/6-card/en.md":"4feed7a9e4b825a50b3c9c606e356baff5a2c81982205d2fb6819d1e23ff9257","cards/6-card/vi.md":"000eaece2bd9616e970f7ef530a78303b25e7c422f317742b7da8e4037c892af","cards/7-card/en.md":"d8f660a3a0e0ea40e40e2519d834e1327bba1e6e613ebf14072089484479362d","cards/7-card/vi.md":"3183a3fca46f7fe40b400b395b9e314b501ff4a2ac6788ff73afe75ae2ccdca8","cards/8-card/en.md":"0dfa504c9c721bf26588594729f2d6e1fdd78a4e5fcf0dc13bf7a17ae6fd7c81","cards/8-card/vi.md":"4ffa13ce60f88fecea961cd232228b8caac5bf7f5ade8386c157565edf4b71c0","cards/9-card/en.md":"8cc37e7ef748e869442de9e1e7a3b4fcbf477fa0170b446658ca95801e1fc57a","cards/9-card/vi.md":"cd85c57f3c1e28b89d506297fd7c1aef7fc66c303d6e28c51f1eab7b7824a76c","en.md":"0f74f32923fdf6aa944abbc4842cbefa5cd2f7985533f4fac0b5997c3e88b2dc","vi.md":"199ba7ed28be04f2e78a7228d7d49edb854e92b787d0aae531d0d15e22d15ebe"}$j$::jsonb, now()) ON CONFLICT (deck_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:1-system-design-mastery/0-core-concepts-and-tradeoffs/0$t$, '231d8cc57', $t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, 0, false, $t$junior$t$, NULL, $j${"vi":{"question":"Một máy chạy toàn bộ ứng dụng của bạn và nó vẫn ổn suốt nhiều tháng. Vì sao một kỹ sư senior vẫn gọi đó là một sự cố đang chờ xảy ra, và cách khắc phục là gì?","tags":["Fault Tolerance","Availability"]},"en":{"question":"One machine runs your whole app and it has been fine for months. Why does a senior engineer still call that an outage waiting to happen, and what is the fix?","tags":["Fault Tolerance","Availability"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nMáy đó là một {{c1::single point of failure (SPOF)::bottleneck,hot node}} — nó chưa hỏng không có nghĩa nó không thể hỏng, chỉ cần nó chết là toàn bộ ứng dụng chết theo. Cách khắc phục là chạy nhiều máy giống nhau (redundancy) và đặt một load balancer phía trước để phân phối traffic.\n\n:::muted\nCơ chế\n:::\nCó ít nhất hai instance chạy song song nghĩa là một máy chết vẫn còn máy khác phục vụ request; load balancer theo dõi máy nào còn sống và chỉ gửi traffic tới những máy đó.\n\n:::muted\nTrade-off\n:::\nĐổi lại là chi phí thật — bạn trả tiền cho nhiều hơn một máy suốt cả tháng dù chỉ để phòng hờ, cộng thêm chi phí và độ phức tạp vận hành của chính load balancer.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy nếu bản thân load balancer đó là máy duy nhất, bạn vừa dời SPOF đi đâu chứ chưa xoá nó?","clozes":[{"n":1,"term":"single point of failure (SPOF)","distractors":["bottleneck","hot node"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nThat machine is a {{c1::single point of failure (SPOF)::bottleneck,hot node}} — it hasn't failed yet doesn't mean it can't, and the moment it dies the whole app dies with it. The fix is running multiple identical instances (redundancy) with a load balancer in front distributing traffic.\n\n:::muted\nHow it works\n:::\nHaving at least two instances running side by side means one machine dying still leaves another to serve requests; the load balancer tracks which machines are alive and only routes traffic to those.\n\n:::muted\nTrade-off\n:::\nThe trade-off is real cost — you pay for more than one machine every month just for insurance, plus the operational cost and complexity of the load balancer itself.\n\n:::muted\nGo deeper\n:::\nso if that load balancer is itself the only machine, did you just move the SPOF instead of removing it?","clozes":[{"n":1,"term":"single point of failure (SPOF)","distractors":["bottleneck","hot node"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:1-system-design-mastery/0-core-concepts-and-tradeoffs/1$t$, '231d8cc57', $t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, 1, false, $t$junior$t$, NULL, $j${"vi":{"question":"Một đồng nghiệp nói \"API của tụi mình nhanh lắm — xử lý được 10.000 request mỗi giây.\" Vì sao câu đó âm thầm gộp hai thứ hoàn toàn khác nhau làm một?","tags":["Latency","Throughput"]},"en":{"question":"A teammate says \"our API is fast — it does 10,000 requests per second.\" Why is that sentence quietly conflating two different things?","tags":["Latency","Throughput"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\n\"Nhanh\" là cảm giác về thời gian chờ của một request, còn con số 10.000 request mỗi giây là {{c1::throughput::latency,bandwidth}} — tổng khối lượng hệ thống xử lý được. Một hệ thống có throughput cao vẫn có thể khiến từng người dùng chờ rất lâu.\n\n:::muted\nCơ chế\n:::\nLatency là thời gian từ lúc gửi request tới lúc nhận response cho đúng một request; throughput là số request xử lý xong trong một đơn vị thời gian, tính trên toàn hệ thống.\n\n:::muted\nTrade-off\n:::\nHai chỉ số này thường đánh đổi nhau: gom nhiều request lại xử lý theo lô (batching) đẩy throughput lên cao hơn, nhưng từng request phải chờ lâu hơn để được gộp vào lô.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy nếu chỉ nhìn con số latency trung bình trên dashboard, bạn đang bỏ sót điều gì?","clozes":[{"n":1,"term":"throughput","distractors":["latency","bandwidth"]}]},"en":{"answer":":::muted\nTL;DR\n:::\n\"Fast\" is a feeling about how long one request waits, while 10,000 requests per second is {{c1::throughput::latency,bandwidth}} — the total volume the system handles. A system with high throughput can still make every single user wait a long time.\n\n:::muted\nHow it works\n:::\nLatency is the time from sending one request to receiving its response; throughput is how many requests finish per unit of time, measured across the whole system.\n\n:::muted\nTrade-off\n:::\nThe two usually trade off against each other: batching requests together to process as a group raises throughput, but each individual request now waits longer to be included in a batch.\n\n:::muted\nGo deeper\n:::\nso if you only look at the average latency number on a dashboard, what are you missing?","clozes":[{"n":1,"term":"throughput","distractors":["latency","bandwidth"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:1-system-design-mastery/0-core-concepts-and-tradeoffs/2$t$, '231d8cc57', $t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, 2, false, $t$junior$t$, NULL, $j${"vi":{"question":"Server duy nhất của bạn đang cháy CPU. Bạn có thể mua một máy mạnh hơn hoặc thêm nhiều máy. Vì sao các kỹ sư nhiều kinh nghiệm coi \"mua máy mạnh hơn\" chỉ là mua thêm thời gian, không phải một cách giải quyết thật sự?","tags":["Scalability","Trade-offs"]},"en":{"question":"Your single server is pegging its CPU. You can buy a bigger box or add more boxes. Why do experienced engineers treat \"bigger box\" as only buying time, not a real fix?","tags":["Scalability","Trade-offs"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nMua máy mạnh hơn là {{c1::vertical scaling (scale up)::horizontal scaling,sharding}} — nó luôn đụng trần phần cứng vật lý sớm hay muộn, và trong suốt thời gian đó máy vẫn chỉ là một điểm chết duy nhất.\n\n:::muted\nCơ chế\n:::\nScale up nâng cấp CPU/RAM của cùng một máy nên không cần đổi kiến trúc, nhưng phần cứng có giới hạn cứng; scale out thêm nhiều máy chạy song song là con đường sống còn để tăng công suất vô hạn định hơn.\n\n:::muted\nTrade-off\n:::\nCái giá của scale out là độ phức tạp kiến trúc thật sự — ứng dụng phải chịu được chạy đa instance, dữ liệu phải chia sẻ hoặc đồng bộ được giữa các máy, thay vì cứ sống yên trong RAM của một máy.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy điều kiện tiên quyết nào một dịch vụ phải có trước khi bạn có thể yên tâm thêm máy?","clozes":[{"n":1,"term":"vertical scaling (scale up)","distractors":["horizontal scaling","sharding"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nBuying a bigger box is {{c1::vertical scaling (scale up)::horizontal scaling,sharding}} — it always hits a physical hardware ceiling sooner or later, and the whole time it's still a single point of failure.\n\n:::muted\nHow it works\n:::\nScaling up upgrades the CPU/RAM of the same machine so nothing about the architecture has to change, but hardware has a hard limit; scaling out by running more machines in parallel is the path with far more room to grow.\n\n:::muted\nTrade-off\n:::\nThe cost of scaling out is real architectural complexity — the application has to tolerate running as multiple instances, and data has to be shared or synchronized across machines instead of just living in one machine's RAM.\n\n:::muted\nGo deeper\n:::\nso what precondition does a service need before you can safely add more machines?","clozes":[{"n":1,"term":"vertical scaling (scale up)","distractors":["horizontal scaling","sharding"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:1-system-design-mastery/0-core-concepts-and-tradeoffs/3$t$, '231d8cc57', $t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, 3, true, $t$junior$t$, NULL, $j${"vi":{"question":"Ai cũng nói một service phải \"stateless\" trước khi đặt nó sau load balancer và thêm node. Stateless ở đây thực chất nghĩa là gì, và điều gì sẽ hỏng ngay khi nó không còn đúng?","tags":["Statelessness","Scalability"]},"en":{"question":"Everyone says a service must be \"stateless\" before you can put it behind a load balancer and add nodes. What does stateless actually mean here, and what breaks the moment it isn't?","tags":["Statelessness","Scalability"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\n{{c1::stateless::stateful,idempotent}} nghĩa là một node không giữ session hay state của người dùng trong bộ nhớ riêng của nó — bất kỳ node nào cũng có thể trả lời bất kỳ request nào.\n\n:::muted\nCơ chế\n:::\nMuốn vậy, state dùng chung phải được đẩy ra một nơi lưu trữ tập trung mà mọi node cùng đọc được, ví dụ Redis hoặc database, thay vì nằm trong RAM của từng node riêng lẻ.\n\n:::muted\nBẫy thường gặp\n:::\nNếu một request bị load balancer định tuyến tới một node không có session đó trong RAM, người dùng đột nhiên bị đăng xuất hoặc mất dữ liệu đang thao tác — dù chẳng có gì \"hỏng\" thật sự, chỉ là state nằm sai chỗ.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy nếu ai đó cố \"sửa\" lỗi này bằng cách ghim một người dùng luôn vào đúng một node, họ vừa đánh đổi điều gì?","clozes":[{"n":1,"term":"stateless","distractors":["stateful","idempotent"]}]},"en":{"answer":":::muted\nTL;DR\n:::\n{{c1::stateless::stateful,idempotent}} means a node doesn't hold the user's session or state in its own private memory — any node can answer any request.\n\n:::muted\nHow it works\n:::\nFor that to work, shared state has to be pushed out to a central store every node can read, like Redis or a database, instead of living in each individual node's RAM.\n\n:::muted\nCommon pitfall\n:::\nIf a request gets routed by the load balancer to a node that doesn't have that session in RAM, the user suddenly gets logged out or loses whatever they were doing — nothing is technically \"broken\", the state is just in the wrong place.\n\n:::muted\nGo deeper\n:::\nso if someone tries to \"fix\" this by pinning a given user to always hit the same node, what did they just trade away?","clozes":[{"n":1,"term":"stateless","distractors":["stateful","idempotent"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:1-system-design-mastery/0-core-concepts-and-tradeoffs/4$t$, '231d8cc57', $t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, 4, true, $t$junior$t$, NULL, $j${"vi":{"question":"Dashboard của bạn ghi latency trung bình là 40ms và cả team đang yên tâm, nhưng support vẫn liên tục nhận ticket than phiền \"chậm quá\". Con số trung bình đang giấu điều gì?","tags":["Latency","Availability"]},"en":{"question":"Your dashboard says average latency is 40ms and the team is relaxed, but support keeps getting \"it's slow\" tickets. What is the average hiding from you?","tags":["Latency","Availability"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nTrung bình đang che giấu {{c1::tail latency (P99)::average,median (P50)}} — phần đuôi chậm nhất của phân phối, nơi một nhóm nhỏ người dùng đang chịu trải nghiệm tệ hơn hẳn số đông.\n\n:::muted\nCơ chế\n:::\nP95/P99 cho biết chính xác 1% hoặc 5% request chậm nhất đang mất bao lâu; ở quy mô hàng triệu người dùng, 1% đó vẫn là hàng chục nghìn người thực sự đang chờ lâu mỗi ngày.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy khi lên kế hoạch năng lực hệ thống, vì sao bạn nên tính theo lúc cao điểm chứ không phải theo mức trung bình?","clozes":[{"n":1,"term":"tail latency (P99)","distractors":["average","median (P50)"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nThe average is hiding {{c1::tail latency (P99)::average,median (P50)}} — the slowest tail of the distribution, where a small group of users is getting a far worse experience than everyone else.\n\n:::muted\nHow it works\n:::\nP95/P99 tell you exactly how long the slowest 1% or 5% of requests take; at a scale of millions of users, that 1% is still tens of thousands of people genuinely waiting a long time every day.\n\n:::muted\nGo deeper\n:::\nso when doing capacity planning, why should you size for peak load instead of the average?","clozes":[{"n":1,"term":"tail latency (P99)","distractors":["average","median (P50)"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:1-system-design-mastery/0-core-concepts-and-tradeoffs/5$t$, '231d8cc57', $t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, 5, true, $t$junior$t$, NULL, $j${"vi":{"question":"Người phỏng vấn hỏi \"SQL hay NoSQL tốt hơn?\" Vì sao câu trả lời \"NoSQL, vì nó scale tốt hơn\" là một câu trả lời đáng báo động, và một ứng viên giỏi sẽ chọn cách trả lời nào thay vào đó?","tags":["Trade-offs","Distributed Systems"]},"en":{"question":"An interviewer asks \"is SQL or NoSQL better?\" Why is \"NoSQL, it scales better\" a red-flag answer, and what framing does a strong candidate reach for instead?","tags":["Trade-offs","Distributed Systems"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nKhông có lựa chọn nào tốt hơn một cách phổ quát — mọi quyết định công nghệ đều là một đánh đổi, và câu trả lời đúng luôn là {{c1::it depends (requirements-driven)::popularity,benchmarks}}, tuỳ vào yêu cầu thật của bài toán.\n\n:::muted\nCơ chế\n:::\nỨng viên giỏi sẽ hỏi ngược lại về requirements — tải bao nhiêu, dữ liệu có cần join phức tạp không, hệ thống cần consistency chặt hay có thể chấp nhận eventual — rồi mới chọn công nghệ dựa trên những con số và access pattern đó.\n\n:::muted\nBẫy thường gặp\n:::\nChọn công nghệ trước khi làm rõ các yêu cầu phi chức năng chính là over-engineering — bạn đang giải quyết một bài toán mình tưởng tượng ra, không phải bài toán thật.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy bước cụ thể nào giúp biến câu \"tuỳ\" mơ hồ đó thành một con số rõ ràng để quyết định?","clozes":[{"n":1,"term":"it depends (requirements-driven)","distractors":["popularity","benchmarks"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nThere is no universally-better choice — every technology decision is a trade-off, and the right answer is always {{c1::it depends (requirements-driven)::popularity,benchmarks}}, depending on the actual requirements of the problem.\n\n:::muted\nHow it works\n:::\nA strong candidate asks about the requirements first — how much load, does the data need complex joins, does the system need strict consistency or can it tolerate eventual — and only then picks a technology based on those numbers and the access pattern.\n\n:::muted\nCommon pitfall\n:::\nPicking a technology before clarifying the non-functional requirements is over-engineering — you're solving a problem you imagined, not the real one.\n\n:::muted\nGo deeper\n:::\nso what concrete step turns that vague \"it depends\" into an actual number you can decide on?","clozes":[{"n":1,"term":"it depends (requirements-driven)","distractors":["popularity","benchmarks"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:1-system-design-mastery/0-core-concepts-and-tradeoffs/6$t$, '231d8cc57', $t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, 6, true, $t$junior$t$, NULL, $j${"vi":{"question":"Một node trong cluster của bạn âm thầm chết lúc 3 giờ sáng và người dùng chẳng ai nhận ra. Cơ chế nào khiến việc chuyển tải này vô hình như vậy, và load balancer làm sao biết được node đó đã chết?","tags":["Fault Tolerance","Load Balancing"]},"en":{"question":"A node in your cluster dies silently at 3am and users never notice. What mechanism made that invisible failover possible, and how does the load balancer even know the node is gone?","tags":["Fault Tolerance","Load Balancing"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nLoad balancer liên tục gửi {{c1::health check::heartbeat,readiness probe}} — những request ping HTTP hoặc TCP nhỏ, định kỳ — tới từng node để biết node nào còn sống.\n\n:::muted\nCơ chế\n:::\nKhi một node không trả lời đủ số lần liên tiếp để vượt ngưỡng thất bại, load balancer loại nó khỏi danh sách và dồn traffic sang các node còn khoẻ; khi node đó hồi phục và trả lời lại bình thường, nó được thêm trở lại vào vòng quay.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy nếu ngưỡng thất bại đó được đặt quá nhạy, điều gì xảy ra với những node vốn dĩ vẫn khoẻ mạnh?","clozes":[{"n":1,"term":"health check","distractors":["heartbeat","readiness probe"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nThe load balancer keeps sending {{c1::health check::heartbeat,readiness probe}} pings — small, periodic HTTP or TCP requests — to every node to know which ones are still alive.\n\n:::muted\nHow it works\n:::\nWhen a node fails to respond enough times in a row to cross a failure threshold, the load balancer evicts it from the pool and shifts traffic to the healthy nodes; once that node recovers and starts responding normally again, it gets added back into the rotation.\n\n:::muted\nGo deeper\n:::\nso if that failure threshold is set too sensitively, what happens to nodes that were actually healthy the whole time?","clozes":[{"n":1,"term":"health check","distractors":["heartbeat","readiness probe"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:1-system-design-mastery/0-core-concepts-and-tradeoffs/7$t$, '231d8cc57', $t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, 7, true, $t$middle$t$, NULL, $j${"vi":{"question":"Để giữ một người dùng đã đăng nhập tiếp tục làm việc trơn tru, có người đề xuất ghim mọi request của người đó vào đúng một node giữ session. Vì sao điều đó âm thầm phá vỡ chính mục đích của việc scale out?","tags":["Statelessness","Load Balancing"]},"en":{"question":"To keep a logged-in user working, someone proposes pinning each user's requests to the one node that holds their session. Why does that quietly defeat the point of scaling out?","tags":["Statelessness","Load Balancing"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nCách đó gọi là {{c1::sticky session::round-robin,IP hash}} — ghim mỗi người dùng vào một node cố định — và nó khiến tải không còn được phân đều nữa, đi ngược lại chính lý do bạn thêm nhiều node.\n\n:::muted\nCơ chế\n:::\nLoad balancer buộc phải nhớ \"người dùng này thuộc node nào\" (thường qua cookie hoặc IP hash) và luôn định tuyến đúng người đó về đúng node, bất kể node kia đang rảnh hay bận.\n\n:::muted\nBẫy thường gặp\n:::\nTệ hơn cả việc lệch tải: nếu đúng node đó chết, mọi người dùng đang ghim vào nó bị đăng xuất ngay lập tức — bạn vừa tạo ra một SPOF thu nhỏ, và cách này chỉ che giấu vấn đề thật chứ không giải quyết nó.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy state đó lẽ ra nên nằm ở đâu để bất kỳ node nào cũng phục vụ được người dùng này?","clozes":[{"n":1,"term":"sticky session","distractors":["round-robin","IP hash"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nThat's called a {{c1::sticky session::round-robin,IP hash}} — pinning each user to one fixed node — and it means load is no longer spread evenly, which works against the exact reason you added more nodes.\n\n:::muted\nHow it works\n:::\nThe load balancer has to remember \"this user belongs to this node\" (usually via a cookie or an IP hash) and always routes that user back to the same node, regardless of whether another node is idle or overloaded.\n\n:::muted\nCommon pitfall\n:::\nWorse than the uneven load: if that one node dies, every user pinned to it gets logged out instantly — you just created a mini single point of failure, and this approach only hides the real problem instead of solving it.\n\n:::muted\nGo deeper\n:::\nso where should that state actually live so any node can serve this user?","clozes":[{"n":1,"term":"sticky session","distractors":["round-robin","IP hash"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:1-system-design-mastery/0-core-concepts-and-tradeoffs/8$t$, '231d8cc57', $t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, 8, true, $t$middle$t$, NULL, $j${"vi":{"question":"Một ứng viên nói hệ thống multi-region của họ là \"CA — vừa consistent vừa available.\" Vì sao điều đó bất khả thi về mặt vật lý trên internet công cộng, và điều gì buộc phải có sự lựa chọn?","tags":["CAP Theorem","Distributed Systems"]},"en":{"question":"A candidate says their multi-region system is \"CA — consistent and available.\" Why is that physically impossible on the public internet, and what forces the choice?","tags":["CAP Theorem","Distributed Systems"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nTrên một hệ phân tán thật, {{c1::network partition (P)::outage,latency spike}} là điều không thể tránh khỏi — đường truyền đứt, gói tin rớt, hay một tiến trình bị treo do GC pause — nên bạn buộc phải hy sinh consistency hoặc availability ngay khi nó xảy ra.\n\n:::muted\nCơ chế\n:::\nKhi partition xảy ra, một node không thể phân biệt được \"node kia đã chết\" với \"chỉ là đường truyền bị cắt\", nên nó phải chọn: hoặc từ chối phục vụ để đảm bảo dữ liệu nhất quán, hoặc tiếp tục phục vụ và chấp nhận dữ liệu có thể lệch nhau. CA thuần tuý chỉ tồn tại trên một máy đơn, nơi không có mạng để mà đứt.\n\n:::muted\nBẫy thường gặp\n:::\nTin rằng một hệ thống multi-region có thể được thiết kế để luôn CA giống như hệ thống một máy — đó là hiểu sai bản chất, vì network partition không phải một sự cố hiếm mà là một điều kiện luôn tiềm ẩn của mạng phân tán.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy khi mạng đang hoàn toàn khoẻ mạnh, không có partition nào cả, sự đánh đổi consistency vẫn còn tồn tại hay đã biến mất?","clozes":[{"n":1,"term":"network partition (P)","distractors":["outage","latency spike"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nOn a real distributed system, a {{c1::network partition (P)::outage,latency spike}} is unavoidable — links get cut, packets get dropped, or a process freezes from a GC pause — so you're forced to sacrifice consistency or availability the moment it happens.\n\n:::muted\nHow it works\n:::\nDuring a partition, a node can't tell \"that peer is dead\" apart from \"the link just got cut\", so it has to choose: refuse to serve in order to guarantee consistent data, or keep serving and accept that data may diverge. Pure CA only exists on a single machine, where there's no network to partition in the first place.\n\n:::muted\nCommon pitfall\n:::\nBelieving a multi-region system can be architected to always stay CA the way a single-machine system can — that misreads the theorem, because a network partition isn't a rare incident, it's an ever-present condition of a distributed network.\n\n:::muted\nGo deeper\n:::\nso when the network is perfectly healthy and there's no partition at all, does the consistency trade-off still exist or has it disappeared?","clozes":[{"n":1,"term":"network partition (P)","distractors":["outage","latency spike"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:1-system-design-mastery/0-core-concepts-and-tradeoffs/9$t$, '231d8cc57', $t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, 9, true, $t$middle$t$, NULL, $j${"vi":{"question":"Một đồng nghiệp khăng khăng hệ thống AP của họ \"vẫn nhất quán, chỉ là chậm hơn thôi.\" Hãy phân tích rõ eventual consistency thực sự cam kết điều gì so với strong consistency, và \"chậm hơn\" đó gây hại ở đâu?","tags":["Consistency","CAP Theorem"]},"en":{"question":"A colleague insists their AP system is \"still consistent, just later.\" Unpack what \"eventual consistency\" really promises versus strong consistency, and where \"later\" bites.","tags":["Consistency","CAP Theorem"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\n{{c1::eventual consistency::strong consistency,causal consistency}} chỉ cam kết các node sẽ hội tụ về cùng một giá trị sau khi ngừng ghi, không cam kết mọi lần đọc ngay lúc này đều thấy dữ liệu mới nhất như strong consistency.\n\n:::muted\nCơ chế\n:::\nStrong consistency nghĩa là mọi node đồng ý ngay lập tức về giá trị mới nhất tại thời điểm đọc; eventual consistency chấp nhận các node phân kỳ tạm thời rồi mới đồng bộ lại khi không còn ghi mới nào tới.\n\n:::muted\nBẫy thường gặp\n:::\nTrong cửa sổ phân kỳ đó, một request có thể đọc phải dữ liệu cũ, hoặc tệ hơn, hai request cùng dựa vào một giá trị chưa cập nhật để rồi dẫn tới double-spend hay ghi đè mất mát.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy khi hai node trong cửa sổ đó ghi hai giá trị khác nhau cho cùng một khoá, ai là người thắng cuộc?","clozes":[{"n":1,"term":"eventual consistency","distractors":["strong consistency","causal consistency"]}]},"en":{"answer":":::muted\nTL;DR\n:::\n{{c1::eventual consistency::strong consistency,causal consistency}} only promises the nodes will converge to the same value after writes stop — it does not promise every read right now sees the latest data the way strong consistency does.\n\n:::muted\nHow it works\n:::\nStrong consistency means every node agrees on the latest value the instant you read; eventual consistency accepts the nodes diverging temporarily and only re-syncing once no new writes are coming in.\n\n:::muted\nCommon pitfall\n:::\nInside that divergence window, a request can read stale data, or worse, two requests can each rely on a value that hasn't updated yet, leading to a double-spend or a silently lost write.\n\n:::muted\nGo deeper\n:::\nso when two nodes inside that window each write a different value for the same key, who wins?","clozes":[{"n":1,"term":"eventual consistency","distractors":["strong consistency","causal consistency"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:1-system-design-mastery/0-core-concepts-and-tradeoffs/10$t$, '231d8cc57', $t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, 10, true, $t$middle$t$, NULL, $j${"vi":{"question":"Hai hệ thống cùng gặp một network partition: một sổ cái ngân hàng và một bộ đếm lượt \"thích\" trên mạng xã hội. Mỗi bên nên chọn phía nào của CAP, và cái giá thật sự phải trả là gì?","tags":["CAP Theorem","Consistency"]},"en":{"question":"Two systems face the same network partition: a bank ledger and a social \"like\" counter. Which side of CAP should each pick, and what is the actual failure you're trading away?","tags":["CAP Theorem","Consistency"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nSổ cái ngân hàng nên chọn {{c1::consistency (CP)::availability (AP)}} — thà từ chối ghi tạm thời hoặc trả lỗi còn hơn để hai bản ghi lệch nhau; bộ đếm lượt thích nên chọn availability (AP) vì một con số sai lệch trong chốc lát chẳng gây hại gì.\n\n:::muted\nCơ chế\n:::\nCP thực hiện bằng cách đồng bộ trước khi commit và huỷ giao dịch nếu quá thời gian chờ, chấp nhận đứng yên còn hơn ghi sai; AP thì commit ngay tại chỗ rồi đồng bộ nền sau, chấp nhận tạm thời lệch để đổi lấy luôn phản hồi được người dùng.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy có con đường trung dung nào giữa việc chờ mọi node đồng ý (CP nghiêm ngặt) và bỏ qua chúng hoàn toàn (AP) không?","clozes":[{"n":1,"term":"consistency (CP)","distractors":["availability (AP)"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nThe bank ledger should pick {{c1::consistency (CP)::availability (AP)}} — better to briefly refuse a write or return an error than let two records diverge; the like counter should pick availability (AP) since a briefly wrong number is harmless.\n\n:::muted\nHow it works\n:::\nCP works by syncing before commit and aborting the transaction on a timeout, accepting downtime over a wrong write; AP commits locally right away and syncs in the background afterward, accepting a brief divergence in exchange for always responding to the user.\n\n:::muted\nGo deeper\n:::\nso is there a middle ground between waiting for every node to agree (strict CP) and skipping them entirely (AP)?","clozes":[{"n":1,"term":"consistency (CP)","distractors":["availability (AP)"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:1-system-design-mastery/0-core-concepts-and-tradeoffs/11$t$, '231d8cc57', $t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, 11, true, $t$middle$t$, NULL, $j${"vi":{"question":"Bạn thêm một load balancer trước năm app server để xoá bỏ single point of failure. Một reviewer nói \"bạn chưa xoá SPOF, chỉ vừa dời nó thôi.\" Họ nói đúng không, và làm sao khắc phục cho triệt để?","tags":["Fault Tolerance","Load Balancing"]},"en":{"question":"You added a load balancer in front of five app servers to kill the single point of failure. A reviewer says \"you didn't remove the SPOF, you just moved it.\" Are they right, and how do you actually fix it?","tags":["Fault Tolerance","Load Balancing"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nĐúng — một load balancer duy nhất chỉ {{c1::relocates (moves, not removes)::removes,eliminates}} điểm chết đó, nó không xoá bỏ gì cả: bản thân load balancer chết là toàn bộ lối vào cũng chết theo.\n\n:::muted\nCơ chế\n:::\nKhắc phục triệt để nghĩa là chạy một cặp load balancer active-passive (hoặc active-active) cùng chia sẻ một địa chỉ ảo qua Keepalived/VRRP, hoặc dùng managed load balancer đa vùng khả dụng của nhà cung cấp cloud.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy nguyên tắc redundancy nào nằm bên dưới cách khắc phục này, áp dụng chung cho bất kỳ thành phần nào trong hệ thống?","clozes":[{"n":1,"term":"relocates (moves, not removes)","distractors":["removes","eliminates"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nYes — a single load balancer only {{c1::relocates (moves, not removes)::removes,eliminates}} that point of failure, it removes nothing: if that load balancer dies, the entire entry point dies with it.\n\n:::muted\nHow it works\n:::\nThe real fix is running an active-passive (or active-active) pair of load balancers sharing a virtual IP via Keepalived/VRRP, or using a cloud provider's multi-AZ managed load balancer.\n\n:::muted\nGo deeper\n:::\nso what redundancy principle sits underneath this fix, one that applies to any component in the system?","clozes":[{"n":1,"term":"relocates (moves, not removes)","distractors":["removes","eliminates"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:1-system-design-mastery/0-core-concepts-and-tradeoffs/12$t$, '231d8cc57', $t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, 12, true, $t$middle$t$, NULL, $j${"vi":{"question":"Trước khi vẽ bất kỳ khối nào, người phỏng vấn muốn bạn ước tính back-of-the-envelope, và cụ thể là QPS lúc cao điểm, không phải QPS trung bình. Vì sao phải ước tính ngay từ đầu, và vì sao chính lúc cao điểm mới là thứ quyết định kiến trúc?","tags":["Capacity Planning","Trade-offs"]},"en":{"question":"Before drawing any boxes, an interviewer wants a back-of-the-envelope estimate, and specifically your peak QPS, not average. Why estimate at all, and why does peak drive the architecture?","tags":["Capacity Planning","Trade-offs"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nƯớc tính biến một bài toán mơ hồ thành một hàm ra quyết định cụ thể; con số quyết định thật sự cần nhìn là {{c1::peak load (peak QPS)::average load,median}}, vì hệ thống sập chính xác vào lúc tải cao nhất chứ không phải lúc trung bình.\n\n:::muted\nCơ chế\n:::\nVí dụ nếu peak QPS ước tính vượt khoảng 1.000, kiến trúc nên nghiêng về hệ lưu trữ phân tán; nếu thấp hơn, một Postgres đơn cùng vài read replica là đủ — con số ước tính chuyển thẳng thành lựa chọn kiến trúc, không còn là cảm tính.\n\n:::muted\nBẫy thường gặp\n:::\nHệ thống thường sập đúng vào những đợt cao điểm thật — flash sale, một bài đăng viral — nên nếu bạn tính công suất theo mức trung bình, bạn gần như chắc chắn sẽ sập đúng lúc quan trọng nhất; sai số bậc-lớn hoặc nhầm đơn vị khi ước tính cũng thường khiến cả kiến trúc lệch hướng.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy trước khi chốt được con số ước tính này, điều gì phải được làm rõ trước?","clozes":[{"n":1,"term":"peak load (peak QPS)","distractors":["average load","median"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nEstimation turns a vague problem into a concrete decision function; the number that actually matters is {{c1::peak load (peak QPS)::average load,median}}, because a system falls over exactly at peak, not at the average.\n\n:::muted\nHow it works\n:::\nFor example, if estimated peak QPS goes past roughly 1,000, the architecture should lean toward a distributed store; below that, a single Postgres with a few read replicas is enough — the estimate translates directly into an architecture choice instead of a gut feeling.\n\n:::muted\nCommon pitfall\n:::\nSystems typically fall over during genuine peak moments — a flash sale, a viral post — so sizing capacity for the average nearly guarantees you collapse exactly when it matters most; order-of-magnitude or unit mistakes while estimating also tend to send the whole architecture in the wrong direction.\n\n:::muted\nGo deeper\n:::\nso what has to be clarified before you can even settle on this estimate?","clozes":[{"n":1,"term":"peak load (peak QPS)","distractors":["average load","median"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:1-system-design-mastery/0-core-concepts-and-tradeoffs/13$t$, '231d8cc57', $t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, 13, true, $t$middle$t$, NULL, $j${"vi":{"question":"Sau một đợt tạm dừng GC ngắn, một node vốn hoàn toàn khoẻ mạnh cứ liên tục bị đánh dấu chết, rồi sống, rồi lại chết — và tải cứ dồn hết sang các node còn lại mỗi lần như vậy. Điều gì đang xảy ra và làm sao để dừng nó lại?","tags":["Fault Tolerance","Availability"]},"en":{"question":"After a brief GC pause, a perfectly healthy node keeps getting marked dead, then alive, then dead again — and load lurches onto the survivors each time. What is happening and how do you calm it?","tags":["Fault Tolerance","Availability"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nĐó là hiện tượng {{c1::flapping::thrashing,throttling}} — ngưỡng health check đặt quá nhạy, chỉ cần một lần phản hồi chậm do GC pause hay tải tăng đột biến là đủ để node bị loại rồi thêm lại liên tục.\n\n:::muted\nCơ chế\n:::\nCách dừng lại là đặt khoảng thời gian kiểm tra hợp lý và tách riêng ngưỡng \"chuyển sang không khoẻ\" với ngưỡng \"chuyển lại khoẻ\", cộng thêm một khoảng thời gian ân hạn (grace period) trước khi loại một node, thay vì loại ngay lập tức chỉ sau một lần thất bại.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy phiên bản tương đương của \"một node bị đóng băng trông giống như đã chết\" ở tầng CAP theorem là gì?","clozes":[{"n":1,"term":"flapping","distractors":["thrashing","throttling"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nThat's {{c1::flapping::thrashing,throttling}} — the health-check threshold is set too sensitively, so a single slow response from a GC pause or a load burst is enough to get the node evicted and re-added over and over.\n\n:::muted\nHow it works\n:::\nThe fix is setting a sensible check interval and keeping separate thresholds for \"flip to unhealthy\" versus \"flip back to healthy\", plus a grace period before evicting a node, instead of evicting it instantly after one failed check.\n\n:::muted\nGo deeper\n:::\nso what's the CAP-theorem-level version of \"a frozen node looks the same as a dead one\"?","clozes":[{"n":1,"term":"flapping","distractors":["thrashing","throttling"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:1-system-design-mastery/0-core-concepts-and-tradeoffs/14$t$, '231d8cc57', $t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, 14, true, $t$senior$t$, NULL, $j${"vi":{"question":"Bạn liên tục thêm replica nhưng throughput đã ngừng tăng — node thứ sáu gần như chẳng giúp gì thêm. Điều gì đang chặn nó lại, và vì sao thêm máy nữa vẫn không phá vỡ được trần đó?","tags":["Scalability","Throughput"]},"en":{"question":"You keep adding replicas but throughput has stopped climbing — the 6th node barely helps. What is capping it, and why can't more machines break through?","tags":["Scalability","Throughput"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nBạn đang đụng một {{c1::shared bottleneck (Amdahl's law)::network latency,a hot node}} — một tài nguyên bị dùng chung và tuần tự hoá, như một database duy nhất, một distributed lock, hay một queue trung tâm.\n\n:::muted\nCơ chế\n:::\nHorizontal scaling chỉ nhân throughput lên khi công việc có thể chia nhỏ và không phải chờ cùng một tài nguyên dùng chung; qua khỏi điểm đó, thêm node chỉ làm tăng tranh chấp (Amdahl's law) và throughput bão hoà dần thay vì tiếp tục tăng tuyến tính.\n\n:::muted\nTrade-off\n:::\nCách phá trần này — sharding, thêm read replica, hoặc loại bỏ hẳn điểm tranh chấp — luôn đổi lấy độ phức tạp vận hành và đôi khi cả consistency, không phải một cú thêm máy đơn giản như trước.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy làm sao bạn chắc chắn rằng chính load balancer không phải là tài nguyên dùng chung đang gây nghẽn?","clozes":[{"n":1,"term":"shared bottleneck (Amdahl's law)","distractors":["network latency","a hot node"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nYou're hitting a {{c1::shared bottleneck (Amdahl's law)::network latency,a hot node}} — a single shared, serialized resource, like one database, a distributed lock, or a central queue.\n\n:::muted\nHow it works\n:::\nHorizontal scaling only multiplies throughput when the work is divisible and doesn't have to wait on the same shared resource; past that point, adding nodes just raises contention (Amdahl's law) and throughput saturates instead of continuing to grow linearly.\n\n:::muted\nTrade-off\n:::\nBreaking through this ceiling — sharding, adding read replicas, or removing the contention point entirely — always trades in operational complexity and sometimes consistency too, not a simple \"add another machine\".\n\n:::muted\nGo deeper\n:::\nso how do you make sure the load balancer itself isn't the shared resource causing the contention?","clozes":[{"n":1,"term":"shared bottleneck (Amdahl's law)","distractors":["network latency","a hot node"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:1-system-design-mastery/0-core-concepts-and-tradeoffs/15$t$, '231d8cc57', $t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, 15, true, $t$senior$t$, NULL, $j${"vi":{"question":"CAP chỉ nói về khoảnh khắc xảy ra partition. Mạng của bạn đang hoàn toàn khoẻ mạnh ngay lúc này — vậy vẫn còn đánh đổi consistency nào không, và khung lý thuyết nào gọi tên nó?","tags":["CAP Theorem","Latency"]},"en":{"question":"CAP only talks about the moment of a partition. Your network is perfectly healthy right now — so is there still a consistency trade-off, and what framework names it?","tags":["CAP Theorem","Latency"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nCó — khung lý thuyết đó là {{c1::PACELC::CAP,BASE}}, mở rộng CAP bằng vế \"Else\": ngay cả khi không có partition, bạn vẫn phải chọn giữa Latency thấp và Consistency cao.\n\n:::muted\nCơ chế\n:::\nVí dụ DynamoDB nghiêng về PA/EL (ưu tiên availability khi partition, ưu tiên latency khi không), còn một hệ lưu trữ đồng bộ chặt nghiêng về PC/EC (ưu tiên consistency cả hai trường hợp) — đây là hai điểm khác nhau trên cùng một trục đánh đổi.\n\n:::muted\nTrade-off\n:::\nĐiều PACELC làm rõ là: đánh đổi consistency để lấy tốc độ không chỉ xảy ra lúc sự cố, mà là một quyết định thiết kế diễn ra liên tục, ngay cả trong ngày bình thường nhất.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy có những hệ thống thật nào là ví dụ cụ thể cho CP so với AP không?","clozes":[{"n":1,"term":"PACELC","distractors":["CAP","BASE"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nYes — that framework is {{c1::PACELC::CAP,BASE}}, extending CAP with an \"Else\" clause: even with no partition, you still choose between low Latency and high Consistency.\n\n:::muted\nHow it works\n:::\nFor example DynamoDB leans PA/EL (favors availability during a partition, favors latency otherwise), while a synchronous store leans PC/EC (favors consistency in both cases) — two different points on the same trade-off axis.\n\n:::muted\nTrade-off\n:::\nWhat PACELC makes explicit is that trading consistency for speed doesn't only happen during an incident — it's a constant design decision, even on the most ordinary day.\n\n:::muted\nGo deeper\n:::\nso what are concrete real systems that land on the CP side versus the AP side?","clozes":[{"n":1,"term":"PACELC","distractors":["CAP","BASE"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:1-system-design-mastery/0-core-concepts-and-tradeoffs/16$t$, '231d8cc57', $t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, 16, true, $t$senior$t$, NULL, $j${"vi":{"question":"Thay vì chờ mọi replica trả lời (CP nghiêm ngặt) hoặc bỏ qua chúng luôn (AP), một hệ lưu trữ tunable cho phép bạn chỉ cần đa số đồng ý. Quy tắc W + R > N đảm bảo đọc được dữ liệu mới như thế nào, và vặn con số đó phải trả giá gì?","tags":["Consensus","Consistency"]},"en":{"question":"Instead of waiting for every replica (strict CP) or skipping them (AP), a tunable store lets you require just a majority. How does the W + R > N rule guarantee a fresh read, and what does turning the knob cost?","tags":["Consensus","Consistency"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nNếu ghi phải chờ W node xác nhận và đọc phải hỏi R node, {{c1::quorum::two-phase commit,replication factor}} với W + R > N đảm bảo tập node được đọc và tập node được ghi luôn giao nhau ở ít nhất một node giữ giá trị mới nhất.\n\n:::muted\nCơ chế\n:::\nKhi W + R ≤ N, hai tập đó hoàn toàn có thể tách rời nhau, và một lần đọc có thể trúng đúng những node chưa nhận được lần ghi mới nhất — dẫn tới đọc phải dữ liệu cũ dù hệ thống vẫn đang chạy bình thường.\n\n:::muted\nTrade-off\n:::\nTăng W hoặc R mua thêm consistency nhưng phải trả bằng latency cao hơn và ít khả dụng hơn — vì mỗi thao tác giờ cần nhiều node phản hồi hơn mới hoàn tất, đúng là đánh đổi CAP nhưng được vặn theo mức tuỳ chỉnh.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy điều gì xảy ra khi một partition chia lá phiếu ra đều hai bên, không bên nào đủ đa số?","clozes":[{"n":1,"term":"quorum","distractors":["two-phase commit","replication factor"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nIf writes wait for W nodes to acknowledge and reads query R nodes, a {{c1::quorum::two-phase commit,replication factor}} with W + R > N guarantees the set of nodes read and the set of nodes written always overlap in at least one node holding the latest value.\n\n:::muted\nHow it works\n:::\nWhen W + R ≤ N, those two sets can be entirely disjoint, and a read can land exactly on the nodes that never received the latest write — producing a stale read even though the system is behaving normally.\n\n:::muted\nTrade-off\n:::\nRaising W or R buys more consistency at the cost of higher latency and lower availability — every operation now needs more nodes to respond before it completes, which is the same CAP trade-off but dialed to a tunable degree.\n\n:::muted\nGo deeper\n:::\nso what happens when a partition splits the votes evenly, and neither side has a majority?","clozes":[{"n":1,"term":"quorum","distractors":["two-phase commit","replication factor"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:1-system-design-mastery/0-core-concepts-and-tradeoffs/17$t$, '231d8cc57', $t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, 17, true, $t$senior$t$, NULL, $j${"vi":{"question":"Một partition chia cluster 4 node của bạn thành hai nửa, mỗi nửa hai node. Đột nhiên không thể ghi được gì nữa, hoặc tệ hơn, bạn lo có tận hai \"leader\" cùng lúc. Gọi tên nguy cơ đó, và hai lựa chọn thiết kế nào ngăn nó xảy ra?","tags":["Consensus","Distributed Systems"]},"en":{"question":"A partition splits your 4-node cluster into two halves of two. Suddenly nothing can be written, or worse, you fear two \"leaders.\" Name the danger and the two design choices that prevent it.","tags":["Consensus","Distributed Systems"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nĐó là nguy cơ {{c1::split-brain::network partition,race condition}} — với một phép chia đều, không nửa nào giữ được đa số, nên một hệ quorum đúng cách sẽ dừng ghi ở cả hai bên để tránh hai leader tồn tại song song.\n\n:::muted\nCơ chế\n:::\nCách phòng ngừa: dùng số node lẻ (3, 5, hoặc 7) để luôn có một bên nắm chắc đa số dù bị chia cắt kiểu gì; và dùng fencing token để một leader cũ vừa quay lại sau khi mất kết nối không thể ghi đè lên dữ liệu mới hơn.\n\n:::muted\nBẫy thường gặp\n:::\nMột sai lầm thường gặp là thêm một node thứ tư vào cluster 3 node \"cho chắc\" — điều đó vô tình đưa cluster về số chẵn và tái tạo lại đúng nguy cơ chia đều phiếu mà bạn đang cố tránh.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy làm sao phát hiện một node bị đóng băng thay vì thật sự đã chết, mà không loại nhầm nó ra khỏi cluster?","clozes":[{"n":1,"term":"split-brain","distractors":["network partition","race condition"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nThat's the danger of {{c1::split-brain::network partition,race condition}} — with an even split, neither half holds a majority, so a properly-built quorum system stops writing on both sides to avoid two leaders coexisting.\n\n:::muted\nHow it works\n:::\nThe prevention: use an odd node count (3, 5, or 7) so one side always holds a clear majority no matter how the split happens, and use a fencing token so a stale leader that just reconnected can't overwrite newer data.\n\n:::muted\nCommon pitfall\n:::\nA common mistake is adding a fourth node to a 3-node cluster \"just to be safe\" — that accidentally makes the cluster an even number, recreating the exact even-split risk you were trying to avoid.\n\n:::muted\nGo deeper\n:::\nso how do you detect a node that's frozen rather than actually dead, without evicting it by mistake?","clozes":[{"n":1,"term":"split-brain","distractors":["network partition","race condition"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:1-system-design-mastery/0-core-concepts-and-tradeoffs/18$t$, '231d8cc57', $t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, 18, true, $t$senior$t$, NULL, $j${"vi":{"question":"Hệ thống AP của bạn để cả hai phía của một partition cùng ghi hai giá trị khác nhau cho cùng một khoá. Đường truyền đã nối lại — bạn quyết định giá trị nào thắng như thế nào, và những lựa chọn thật sự là gì?","tags":["Consistency","Distributed Systems"]},"en":{"question":"Your AP system let both sides of a partition write a different value for the same key. The link is back — how do you decide which value wins, and what are the real options?","tags":["Consistency","Distributed Systems"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nBạn cần một chiến lược {{c1::conflict resolution::rollback,two-phase commit}} tường minh, vì sự phân kỳ là bản chất tất yếu của một hệ AP, không phải một lỗi cần vá.\n\n:::muted\nCơ chế\n:::\nBa lựa chọn phổ biến: Last-Write-Wins chọn theo timestamp mới nhất, đơn giản nhưng có thể âm thầm làm mất một lần ghi thật; Vector Clocks theo dõi quan hệ nhân quả giữa các lần ghi để phát hiện đúng xung đột thật sự; CRDT được thiết kế cấu trúc dữ liệu sao cho tự động hợp nhất mà không cần xung đột.\n\n:::muted\nTrade-off\n:::\nBa lựa chọn đó đánh đổi giữa sự đơn giản và độ chính xác — Last-Write-Wins dễ cài đặt nhất nhưng dễ mất dữ liệu nhất, còn Vector Clocks hay CRDT chính xác hơn thì phức tạp hơn hẳn để triển khai và vận hành đúng.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy lựa chọn CP nào ngay từ đầu đã từ chối cho phép sự phân kỳ đó xảy ra?","clozes":[{"n":1,"term":"conflict resolution","distractors":["rollback","two-phase commit"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nYou need an explicit {{c1::conflict resolution::rollback,two-phase commit}} strategy, because divergence is an intrinsic property of an AP system, not a bug to patch over.\n\n:::muted\nHow it works\n:::\nThree common options: Last-Write-Wins picks by the most recent timestamp, simple but can silently drop a real write; Vector Clocks track causality between writes to detect true conflicts accurately; CRDTs structure the data itself so it auto-merges without ever needing a conflict decision.\n\n:::muted\nTrade-off\n:::\nThese trade simplicity against correctness — Last-Write-Wins is the easiest to implement but the most likely to lose data, while Vector Clocks or CRDTs are more correct but noticeably harder to implement and operate correctly.\n\n:::muted\nGo deeper\n:::\nso which CP choice refuses to let that divergence happen in the first place?","clozes":[{"n":1,"term":"conflict resolution","distractors":["rollback","two-phase commit"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_cards (item_id, version, deck_id, sort_index, is_premium, level, langs, front, back) VALUES ($t$card:1-system-design-mastery/0-core-concepts-and-tradeoffs/19$t$, '231d8cc57', $t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, 19, true, $t$staff$t$, NULL, $j${"vi":{"question":"Traffic tăng gấp 10 lần trong một đợt flash sale và bạn không thể scale kịp để phục vụ hết mọi thứ. Làm sao giữ luồng lõi (checkout/thanh toán) sống sót bằng cách chủ động hy sinh các tính năng khác, và mẫu hình này gọi là gì?","tags":["Availability","Trade-offs"]},"en":{"question":"Traffic 10x's in a flash sale and you cannot scale fast enough to serve everything. How do you keep the core flow (checkout/payment) alive by deliberately sacrificing other features, and what is this pattern called?","tags":["Availability","Trade-offs"]}}$j$::jsonb, $j${"vi":{"answer":":::muted\nTrả lời thẳng\n:::\nMẫu hình đó gọi là {{c1::graceful degradation::load shedding,circuit breaker}} — chủ động tắt các tính năng phụ để dồn tài nguyên cho luồng lõi, tránh để cả hệ thống sập hoàn toàn.\n\n:::muted\nCơ chế\n:::\nVí dụ tắt gợi ý sản phẩm, tắt phân tích/thống kê không thiết yếu, trong khi vẫn giữ checkout và thanh toán chạy đầy đủ; kết hợp cùng auto-scaling, CDN cho tài nguyên tĩnh, rate limiting, và hàng đợi để hấp thụ đợt tăng đột biến.\n\n:::muted\nTrade-off\n:::\nCái giá là trải nghiệm người dùng bị giảm đi tạm thời — mất gợi ý, mất vài widget phụ — nhưng đó là cái giá nhỏ hơn nhiều so với việc toàn bộ hệ thống ngừng hoạt động.\n\n:::muted\nĐào sâu tiếp\n:::\nvậy tín hiệu cụ thể nào (như P99 hay peak QPS) cho bạn biết chính xác lúc nào đã chạm tới cái trần đó?","clozes":[{"n":1,"term":"graceful degradation","distractors":["load shedding","circuit breaker"]}]},"en":{"answer":":::muted\nTL;DR\n:::\nThat pattern is called {{c1::graceful degradation::load shedding,circuit breaker}} — proactively turning off secondary features to channel resources into the core flow instead of letting the whole system crash.\n\n:::muted\nHow it works\n:::\nFor example, turn off recommendations and non-essential analytics while keeping checkout and payment fully functional; pair this with auto-scaling, a CDN for static assets, rate limiting, and queues to absorb the burst.\n\n:::muted\nTrade-off\n:::\nThe cost is a temporarily degraded user experience — no recommendations, some secondary widgets missing — but that's a far smaller price than the entire system going down.\n\n:::muted\nGo deeper\n:::\nso what concrete signal (like P99 or peak QPS) tells you exactly when you've hit that ceiling?","clozes":[{"n":1,"term":"graceful degradation","distractors":["load shedding","circuit breaker"]}]}}$j$::jsonb) ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO review_decks (deck_id, course, sort_index, live_version, difficulty, titles, descriptions, module_refs, tracks, card_count, free_card_count, updated_at) VALUES ($t$1-system-design-mastery/0-core-concepts-and-tradeoffs$t$, $t$1-system-design-mastery$t$, 0, '231d8cc57', $t$hard$t$, $j${"vi":"Khái Niệm Cốt Lõi & Đánh Đổi","en":"Core Concepts & Tradeoffs"}$j$::jsonb, $j${"vi":"20 câu phỏng vấn sâu về những mô hình tư duy mà mọi vòng phỏng vấn system design đều bắt đầu từ đó: SPOF và redundancy, latency vs throughput, vertical vs horizontal scaling, statelessness, health check và flapping, CAP theorem, PACELC, quorum và consensus, split-brain, conflict resolution, capacity planning, và graceful degradation khi quá tải.","en":"20 deep interview cards on the mental models every system design round starts with: SPOF and redundancy, latency vs throughput, vertical vs horizontal scaling, statelessness, health checks and flapping, CAP theorem, PACELC, quorum and consensus, split-brain, conflict resolution, capacity planning, and graceful degradation under load."}$j$::jsonb, $j$["core-concepts-and-metrics","scaling-strategies","cap-theorem-and-tradeoffs","system-design-process"]$j$::jsonb, $j$["system-design-senior"]$j$::jsonb, 20, 3, now()) ON CONFLICT (deck_id) DO NOTHING;
